R["hsgi-p1-subset-sum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <map>\n#include <cmath>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long S; in >> n >> S;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    int h = n / 2;\n    vector<long long> L{0}, R{0};\n    for (int i = 0; i < h; ++i) {\n        size_t sz = L.size();\n        for (size_t m = 0; m < sz; ++m) L.push_back(L[m] + a[i]);\n    }\n    for (int i = h; i < n; ++i) {\n        size_t sz = R.size();\n        for (size_t m = 0; m < sz; ++m) R.push_back(R[m] + a[i]);\n    }\n    sort(R.begin(), R.end());\n    long long best = -1;\n    for (long long x : L) {\n        long long need = S - x;\n        auto it = lower_bound(R.begin(), R.end(), need);\n        if (it != R.end()) {\n            long long d = llabs(x + *it - S);\n            if (best < 0 || d < best) best = d;\n        }\n        if (it != R.begin()) {\n            --it;\n            long long d = llabs(x + *it - S);\n            if (best < 0 || d < best) best = d;\n            ++it;\n        }\n    }\n    out << best << \"\\n\";\n}\n";
W["hsgi-p1-subset-sum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <map>\n#include <cmath>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long S; in >> n >> S;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    int h = n / 2;\n    vector<long long> L{0}, R{0};\n    for (int i = 0; i < h; ++i) {\n        size_t sz = L.size();\n        for (size_t m = 0; m < sz; ++m) L.push_back(L[m] + a[i]);\n    }\n    for (int i = h; i < n; ++i) {\n        size_t sz = R.size();\n        for (size_t m = 0; m < sz; ++m) R.push_back(R[m] + a[i]);\n    }\n    sort(R.begin(), R.end());\n    long long best = -1;\n    for (long long x : L) {\n        long long need = S - x;\n        // near-miss: checks only the ceiling candidate (the first sum\n        // >= S - x) and never the floor \u2014 wrong whenever the closest\n        // subset sum lies just BELOW the target\n        auto it = lower_bound(R.begin(), R.end(), need);\n        if (it == R.end()) continue;\n        long long d = llabs(x + *it - S);\n        if (best < 0 || d < best) best = d;\n    }\n    out << best << \"\\n\";\n}\n";
