R["hsgi-p3-rooms"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<pair<long long,int>> ev;\n    ev.reserve(2 * n);\n    for (int i = 0; i < n; ++i) {\n        long long l, r; in >> l >> r;\n        ev.push_back({r, 0});   // end (0 sorts before +1's at same time)\n        ev.push_back({l, 1});\n    }\n    sort(ev.begin(), ev.end());\n    int cur = 0, rooms = 0;\n    for (auto& [t, d] : ev) {\n        if (d) { ++cur; rooms = max(rooms, cur); }\n        else --cur;\n    }\n    out << rooms << \"\\n\";\n}\n";
W["hsgi-p3-rooms"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<pair<long long,int>> ev;\n    ev.reserve(2 * n);\n    for (int i = 0; i < n; ++i) {\n        long long l, r; in >> l >> r;\n        ev.push_back({r, 1});   // near-miss: end \u0111\u00e1nh d\u1ea5u +1 (nh\u01b0 start)\n        ev.push_back({l, 1});\n    }\n    sort(ev.begin(), ev.end());\n    int cur = 0, rooms = 0;\n    for (auto& [t, d] : ev) {\n        if (d) { ++cur; rooms = max(rooms, cur); }\n        else --cur;\n    }\n    out << rooms << \"\\n\";\n}\n";
R["hsgi-p3-free-time"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long D; int k; in >> D >> k;\n    vector<pair<long long,long long>> all;\n    for (int e = 0; e < k; ++e) {\n        int m; in >> m;\n        for (int i = 0; i < m; ++i) {\n            long long l, r; in >> l >> r;\n            all.push_back({l, r});\n        }\n    }\n    sort(all.begin(), all.end());\n    vector<pair<long long,long long>> busy;\n    for (auto& [l, r] : all) {\n        if (!busy.empty() && l <= busy.back().second)\n            busy.back().second = max(busy.back().second, r);\n        else busy.push_back({l, r});\n    }\n    long long prev = 0;\n    for (auto& [l, r] : busy) {\n        if (l > prev) out << prev << \" \" << l << \"\\n\";\n        prev = max(prev, r);\n    }\n    if (prev < D) out << prev << \" \" << D << \"\\n\";\n}\n";
W["hsgi-p3-free-time"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long D; int k; in >> D >> k;\n    vector<pair<long long,long long>> all;\n    for (int e = 0; e < k; ++e) {\n        int m; in >> m;\n        for (int i = 0; i < m; ++i) {\n            long long l, r; in >> l >> r;\n            all.push_back({l, r});\n        }\n    }\n    sort(all.begin(), all.end());\n    vector<pair<long long,long long>> busy;\n    for (auto& [l, r] : all) {\n        if (!busy.empty() && l <= busy.back().second)\n            busy.back().second = max(busy.back().second, r);\n        else busy.push_back({l, r});\n    }\n    long long prev = 0;\n    for (auto& [l, r] : busy) {\n        // near-miss: in c\u1ea3 kho\u1ea3ng \u0111\u1ed9 d\u00e0i 0 (l == prev) v\u00e0 qu\u00ean \u0111o\u1ea1n \u0111u\u00f4i\n        // sau ca b\u1eadn cu\u1ed1i \u2014 output th\u1eeba d\u00f2ng \"x x\" v\u00e0 thi\u1ebfu \"prev D\"\n        if (l >= prev) out << prev << \" \" << l << \"\\n\";\n        prev = max(prev, r);\n    }\n}\n";
R["hsgi-p3-insert"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<pair<long long,long long>> v(n);\n    for (auto& [l, r] : v) in >> l >> r;\n    long long L, R; in >> L >> R;\n    vector<pair<long long,long long>> res;\n    bool merged = false;\n    for (auto& [l, r] : v) {\n        if (r < L || l > R) {\n            res.push_back({l, r});\n        } else {\n            L = min(L, l);\n            R = max(R, r);\n            if (!merged) { merged = true; }\n        }\n    }\n    res.push_back({L, R});\n    sort(res.begin(), res.end());\n    for (auto& [l, r] : res) out << l << \" \" << r << \"\\n\";\n}\n";
W["hsgi-p3-insert"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<pair<long long,long long>> v(n);\n    for (auto& [l, r] : v) in >> l >> r;\n    long long L, R; in >> L >> R;\n    vector<pair<long long,long long>> res;\n    for (auto& [l, r] : v) {\n        // near-miss: \u0111i\u1ec1u ki\u1ec7n t\u00e1ch l\u00e0 r < L && l > R (AND thay OR) \u2014\n        // g\u1ea7n nh\u01b0 lu\u00f4n sai, \u0111o\u1ea1n ngo\u00e0i tr\u00e1i b\u1ecb h\u1ea5p th\u1ee5 nh\u1ea7m\n        if (r < L && l > R) {\n            res.push_back({l, r});\n        } else {\n            L = min(L, l);\n            R = max(R, r);\n        }\n    }\n    res.push_back({L, R});\n    sort(res.begin(), res.end());\n    for (auto& [l, r] : res) out << l << \" \" << r << \"\\n\";\n}\n";
R["hsgi-cp-m3-busday"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long D; in >> n >> D;\n    // b\u1eadc t\u1ea1i c\u00f9ng th\u1eddi \u0111i\u1ec3m: 0 = start-\u0111i\u1ec3m (l == r, chi\u1ebfm b\u00e0n ngay),\n    // 1 = end (th\u01b0\u1eddng), 2 = start-th\u01b0\u1eddng (t\u00e1i d\u1ee5ng b\u00e0n v\u1eeba g\u1ee1)\n    vector<tuple<long long,int,int>> ev;\n    ev.reserve(2 * n);\n    for (int i = 0; i < n; ++i) {\n        long long l, r; in >> l >> r;\n        if (l == r) {\n            ev.push_back({l, 0, +1});\n            ev.push_back({l, 1, -1});\n        } else {\n            ev.push_back({l, 2, +1});\n            ev.push_back({r, 1, -1});\n        }\n    }\n    sort(ev.begin(), ev.end());\n    int cur = 0, tables = 0;\n    for (auto& [t, k, d] : ev) {\n        cur += d;\n        tables = max(tables, cur);\n    }\n    out << tables << \"\\n\";\n}\n";
W["hsgi-cp-m3-busday"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long D; in >> n >> D;\n    // near-miss: start-\u0111i\u1ec3m x\u1eed l\u00fd SAU end (b\u1eadc 2 nh\u01b0 start-th\u01b0\u1eddng) \u2014\n    // hai l\u01b0\u1ee3t \u0111i\u1ec3m c\u00f9ng th\u1eddi \u0111i\u1ec3m b\u1ecb \u0111\u1ebfm... 0 b\u00e0n v\u00ec \u22121 g\u1ee1 tr\u01b0\u1edbc +1\n    vector<tuple<long long,int,int>> ev;\n    ev.reserve(2 * n);\n    for (int i = 0; i < n; ++i) {\n        long long l, r; in >> l >> r;\n        ev.push_back({l, 2, +1});\n        ev.push_back({r, 1, -1});\n    }\n    sort(ev.begin(), ev.end());\n    int cur = 0, tables = 0;\n    for (auto& [t, k, d] : ev) {\n        cur += d;\n        tables = max(tables, cur);\n    }\n    out << tables << \"\\n\";\n}\n";
R["hsgi-p4-ropes"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    for (int i = 0; i < n; ++i) {\n        long long x; in >> x;\n        pq.push(x);\n    }\n    long long total = 0;\n    while (pq.size() > 1) {\n        long long a = pq.top(); pq.pop();\n        long long b = pq.top(); pq.pop();\n        total += a + b;\n        pq.push(a + b);\n    }\n    out << total << \"\\n\";\n}\n";
W["hsgi-p4-ropes"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    priority_queue<long long> pq;   // near-miss: MAX-heap \u2014 lu\u00f4n gh\u00e9p hai\n    for (int i = 0; i < n; ++i) {   // s\u1ee3i L\u1edaN NH\u1ea4T, t\u1ed1n h\u01a1n tr\u00ean data l\u1ec7ch\n        long long x; in >> x;\n        pq.push(x);\n    }\n    long long total = 0;\n    while (pq.size() > 1) {\n        long long a = pq.top(); pq.pop();\n        long long b = pq.top(); pq.pop();\n        total += a + b;\n        pq.push(a + b);\n    }\n    out << total << \"\\n\";\n}\n";
R["hsgi-p4-edf"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<pair<long long,long long>> j(n);\n    for (auto& [p, d] : j) in >> p >> d;\n    sort(j.begin(), j.end(), [](auto& a, auto& b){ return a.second < b.second; });\n    long long t = 0, worst = 0;\n    for (auto& [p, d] : j) {\n        t += p;\n        worst = max(worst, max(0LL, t - d));\n    }\n    out << worst << \"\\n\";\n}\n";
W["hsgi-p4-edf"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<pair<long long,long long>> j(n);\n    for (auto& [p, d] : j) in >> p >> d;\n    // near-miss: sort theo th\u1eddi gian x\u1eed l\u00fd (SPT) thay v\u00ec deadline \u2014\n    // vi\u1ec7c d\u00e0i c\u00f3 h\u1ea1n s\u1edbm b\u1ecb tr\u1ec5 ph\u1ea1t n\u1eb7ng\n    sort(j.begin(), j.end());\n    long long t = 0, worst = 0;\n    for (auto& [p, d] : j) {\n        t += p;\n        worst = max(worst, max(0LL, t - d));\n    }\n    out << worst << \"\\n\";\n}\n";
R["hsgi-p4-median"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    priority_queue<int> left;\n    priority_queue<int, vector<int>, greater<int>> right;\n    for (int i = 0; i < n; ++i) {\n        int x; in >> x;\n        if (left.empty() || x <= left.top()) left.push(x);\n        else right.push(x);\n        if ((int)left.size() > (int)right.size() + 1) { right.push(left.top()); left.pop(); }\n        if ((int)right.size() > (int)left.size())     { left.push(right.top()); right.pop(); }\n        int m = i + 1;\n        if (m % 2 == 1) out << left.top() << \"\\n\";\n        else            out << right.top() << \"\\n\";\n    }\n}\n";
W["hsgi-p4-median"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    priority_queue<int> everything;   // near-miss: ch\u1ec9 m\u1ed9t max-heap \u2014\n    for (int i = 0; i < n; ++i) {     // in top = MAX c\u1ee7a m\u1ecdi s\u1ed1 \u0111\u00e3 \u0111\u1ecdc\n        int x; in >> x;               // thay v\u00ec trung v\u1ecb tr\u00ean\n        everything.push(x);\n        out << everything.top() << \"\\n\";\n    }\n}\n";
