R["hsgi-p4-slots"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<pair<long long,int>> j(n);   // (w, d)\n    for (auto& [w, d] : j) in >> d >> w;\n    sort(j.begin(), j.end(), [](auto& a, auto& b){ return a.first > b.first; });\n    vector<bool> used(n + 1, false);\n    long long total = 0;\n    for (auto& [w, d] : j) {\n        for (int s = min(d, n); s >= 1; --s) {\n            if (!used[s]) { used[s] = true; total += w; break; }\n        }\n    }\n    out << total << \"\\n\";\n}\n";
W["hsgi-p4-slots"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<pair<long long,int>> j(n);   // (w, d)\n    for (auto& [w, d] : j) in >> d >> w;\n    sort(j.begin(), j.end(), [](auto& a, auto& b){ return a.first > b.first; });\n    vector<bool> used(n + 1, false);\n    long long total = 0;\n    for (auto& [w, d] : j) {\n        // near-miss: chi\u1ebfm khe S\u1edaM NH\u1ea4T c\u00f2n tr\u1ed1ng (\u2264 d) thay v\u00ec mu\u1ed9n nh\u1ea5t \u2014\n        // khe s\u1edbm l\u00e0 t\u00e0i nguy\u00ean khan hi\u1ebfm, vi\u1ec7c h\u1ea1n mu\u1ed9n b\u1ecb \u00e9p b\u1ecf\n        for (int s = 1; s <= min(d, n); ++s) {\n            if (!used[s]) { used[s] = true; total += w; break; }\n        }\n    }\n    out << total << \"\\n\";\n}\n";
R["hsgi-cp-m4-fuel"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long D, T; int n; in >> D >> T >> n;\n    priority_queue<long long> passed;\n    long long pos = 0, fuel = T;\n    int stops = 0;\n    bool impossible = false;\n    for (int i = 0; i < n && !impossible; ++i) {\n        long long p; in >> p;\n        long long g = p - pos;\n        while (fuel < g) {\n            if (passed.empty()) { impossible = true; break; }\n            fuel += passed.top(); passed.pop(); ++stops;\n        }\n        if (impossible) break;\n        fuel -= g;\n        pos = p;\n        passed.push(T);\n    }\n    if (!impossible) {\n        long long g = D - pos;\n        while (fuel < g) {\n            if (passed.empty()) { impossible = true; break; }\n            fuel += passed.top(); passed.pop(); ++stops;\n        }\n    }\n    out << (impossible ? -1 : stops) << \"\\n\";\n}\n";
W["hsgi-cp-m4-fuel"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long D, T; int n; in >> D >> T >> n;\n    // near-miss: tham lam S\u1edaM \u2014 ch\u00e2m t\u1ea1i M\u1eccI tr\u1ea1m \u0111i qua, s\u1ed1 l\u1ea7n d\u1eebng\n    // ph\u1ed3ng tr\u00ean m\u1ecdi data c\u00f3 nhi\u1ec1u tr\u1ea1m li\u00ean ti\u1ebfp\n    long long pos = 0, fuel = T;\n    int stops = 0;\n    bool impossible = false;\n    for (int i = 0; i < n && !impossible; ++i) {\n        long long p; in >> p;\n        long long g = p - pos;\n        if (fuel < g) { impossible = true; break; }\n        fuel -= g;\n        pos = p;\n        ++stops;              // ch\u00e2m d\u00f9 kh\u00f4ng c\u1ea7n\n        fuel = T;\n    }\n    if (!impossible && fuel < D - pos) impossible = true;\n    out << (impossible ? -1 : stops) << \"\\n\";\n}\n";
R["hsgi-p5-dynamic-sum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<long long> t(n + 1, 0);\n    auto add = [&](int i, long long v) {\n        for (; i <= n; i += i & -i) t[i] += v;\n    };\n    auto pre = [&](int i) {\n        long long s = 0;\n        for (; i > 0; i -= i & -i) s += t[i];\n        return s;\n    };\n    for (int i = 1; i <= n; ++i) {\n        long long x; in >> x;\n        add(i, x);\n    }\n    while (q--) {\n        int type; in >> type;\n        if (type == 1) {\n            int i; long long v; in >> i >> v;\n            add(i, v);\n        } else {\n            int l, r; in >> l >> r;\n            out << pre(r) - pre(l - 1) << \"\\n\";\n        }\n    }\n}\n";
W["hsgi-p5-dynamic-sum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<long long> t(n + 1, 0);\n    auto add = [&](int i, long long v) {\n        for (; i <= n; i += i & -i) t[i] += v;\n    };\n    auto pre = [&](int i) {\n        long long s = 0;\n        for (; i > 0; i -= i & -i) s += t[i];\n        return s;\n    };\n    for (int i = 1; i <= n; ++i) {\n        long long x; in >> x;\n        add(i, x);\n    }\n    while (q--) {\n        int type; in >> type;\n        if (type == 1) {\n            int i; long long v; in >> i >> v;\n            add(i, v);\n        } else {\n            int l, r; in >> l >> r;\n            // near-miss: pre(r) - pre(l) b\u1ecf m\u1ea5t a[l]\n            out << pre(r) - pre(l) << \"\\n\";\n        }\n    }\n}\n";
R["hsgi-p5-inversions"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<int> a(n);\n    for (auto& x : a) in >> x;\n    vector<int> vals = a;\n    sort(vals.begin(), vals.end());\n    vals.erase(unique(vals.begin(), vals.end()), vals.end());\n    int m = vals.size();\n    vector<int> t(m + 1, 0);\n    auto add = [&](int i) {\n        for (; i <= m; i += i & -i) t[i] += 1;\n    };\n    auto pre = [&](int i) {\n        int s = 0;\n        for (; i > 0; i -= i & -i) s += t[i];\n        return s;\n    };\n    long long inv = 0;\n    for (int j = 0; j < n; ++j) {\n        int r = lower_bound(vals.begin(), vals.end(), a[j]) - vals.begin() + 1;\n        inv += (long long)j - pre(r);\n        add(r);\n    }\n    out << inv << \"\\n\";\n}\n";
W["hsgi-p5-inversions"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<int> a(n);\n    for (auto& x : a) in >> x;\n    vector<int> vals = a;\n    sort(vals.begin(), vals.end());\n    vals.erase(unique(vals.begin(), vals.end()), vals.end());\n    int m = vals.size();\n    vector<int> t(m + 1, 0);\n    auto add = [&](int i) {\n        for (; i <= m; i += i & -i) t[i] += 1;\n    };\n    auto pre = [&](int i) {\n        int s = 0;\n        for (; i > 0; i -= i & -i) s += t[i];\n        return s;\n    };\n    long long inv = 0;\n    for (int j = 0; j < n; ++j) {\n        int r = lower_bound(vals.begin(), vals.end(), a[j]) - vals.begin() + 1;\n        // near-miss: \u0111\u1ebfm ph\u1ea7n t\u1eed TR\u01af\u1edaC nh\u1ecf h\u01a1n ho\u1eb7c b\u1eb1ng (pre(r) thay v\u00ec\n        // j - pre(r)) \u2014 \u0111\u00f3 l\u00e0 s\u1ed1 NON-inversions, kh\u00f4ng ph\u1ea3i ngh\u1ecbch th\u1ebf\n        inv += pre(r);\n        add(r);\n    }\n    out << inv << \"\\n\";\n}\n";
