W["hsgi-p5-max-seen"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<int> h(n + 1);\n    for (int i = 1; i <= n; ++i) in >> h[i];\n    vector<int> t(n + 1, 0);\n    auto upd = [&](int i, int v) {\n        // near-miss: g\u00e1n = thay v\u00ec max \u2014 node b\u1ecb GHI \u0110\u00c8 khi ph\u1ea7n t\u1eed m\u1edbi\n        // nh\u1ecf h\u01a1n, ph\u00e1 prefix max t\u1ea1i m\u1ecdi node b\u1ecb \u0111\u00e8\n        for (; i <= n; i += i & -i) t[i] = v;\n    };\n    auto pre = [&](int i) {\n        int s = 0;\n        for (; i > 0; i -= i & -i) s = max(s, t[i]);\n        return s;\n    };\n    for (int i = 1; i <= n; ++i) {\n        upd(i, h[i]);\n        out << pre(i) << \"\\n\";\n    }\n}\n";
R["hsgi-p5-distinct"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<int> a(n + 1);\n    for (int i = 1; i <= n; ++i) in >> a[i];\n    vector<vector<pair<int,int>>> byR(n + 1);\n    for (int i = 0; i < q; ++i) {\n        int l, r; in >> l >> r;\n        byR[r].push_back({l, i});\n    }\n    vector<int> t(n + 1, 0);\n    auto add = [&](int i, int v) {\n        for (; i <= n; i += i & -i) t[i] += v;\n    };\n    auto pre = [&](int i) {\n        int s = 0;\n        for (; i > 0; i -= i & -i) s += t[i];\n        return s;\n    };\n    vector<int> last(200001, -1), ans(q);\n    const int OFF = 1000000000;\n    vector<int> lastAt;\n    // map value -> last position via compressed dict\n    vector<int> vals = a;\n    sort(vals.begin(), vals.end());\n    vals.erase(unique(vals.begin(), vals.end()), vals.end());\n    vector<int> lst(vals.size(), -1);\n    for (int i = 1; i <= n; ++i) {\n        int r = lower_bound(vals.begin(), vals.end(), a[i]) - vals.begin();\n        if (lst[r] != -1) add(lst[r], -1);\n        add(i, 1);\n        lst[r] = i;\n        for (auto& [l, idx] : byR[i]) ans[idx] = pre(i) - pre(l - 1);\n    }\n    for (int i = 0; i < q; ++i) out << ans[i] << \"\\n\";\n}\n";
W["hsgi-p5-distinct"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<int> a(n + 1);\n    for (int i = 1; i <= n; ++i) in >> a[i];\n    vector<vector<pair<int,int>>> byR(n + 1);\n    for (int i = 0; i < q; ++i) {\n        int l, r; in >> l >> r;\n        byR[r].push_back({l, i});\n    }\n    vector<int> t(n + 1, 0);\n    auto add = [&](int i, int v) {\n        for (; i <= n; i += i & -i) t[i] += v;\n    };\n    auto pre = [&](int i) {\n        int s = 0;\n        for (; i > 0; i -= i & -i) s += t[i];\n        return s;\n    };\n    vector<int> ans(q);\n    vector<int> vals = a;\n    sort(vals.begin(), vals.end());\n    vals.erase(unique(vals.begin(), vals.end()), vals.end());\n    vector<int> lst(vals.size(), -1);\n    for (int i = 1; i <= n; ++i) {\n        int r = lower_bound(vals.begin(), vals.end(), a[i]) - vals.begin();\n        if (lst[r] != -1) add(lst[r], -1);\n        add(i, 1);\n        // near-miss: QU\u00caN c\u1eadp nh\u1eadt lst[r] = i \u2014 v\u1ecb tr\u00ed c\u0169 b\u1ecb x\u00f3a hai l\u1ea7n,\n        // \u0111\u1ebfm thi\u1ebfu gi\u00e1 tr\u1ecb \u0111\u1ea7u m\u1ed7i \u0111o\u1ea1n l\u1eb7p\n        for (auto& [l, idx] : byR[i]) ans[idx] = pre(i) - pre(l - 1);\n    }\n    for (int i = 0; i < q; ++i) out << ans[i] << \"\\n\";\n}\n";
R["hsgi-p5-kquery"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<int> a(n + 1);\n    for (int i = 1; i <= n; ++i) in >> a[i];\n    vector<pair<int,int>> qs(q);\n    for (auto& [pos, k] : qs) in >> pos >> k;\n    vector<int> vals = a;\n    for (auto& [pos, k] : qs) vals.push_back(k);\n    sort(vals.begin(), vals.end());\n    vals.erase(unique(vals.begin(), vals.end()), vals.end());\n    int m = vals.size();\n    vector<int> t(m + 1, 0);\n    auto add = [&](int i, int v) {\n        for (; i <= m; i += i & -i) t[i] += v;\n    };\n    auto pre = [&](int i) {\n        int s = 0;\n        for (; i > 0; i -= i & -i) s += t[i];\n        return s;\n    };\n    auto rank1 = [&](int x) {\n        return lower_bound(vals.begin(), vals.end(), x) - vals.begin() + 1;\n    };\n    vector<vector<pair<int,int>>> byI(n + 1);\n    for (int i = 0; i < q; ++i) byI[qs[i].first].push_back({qs[i].second, i});\n    vector<long long> ans(q);\n    for (int i = 1; i <= n; ++i) {\n        add(rank1(a[i]), 1);\n        for (auto& [k, idx] : byI[i]) {\n            int rk = rank1(k);\n            ans[idx] = (long long)pre(m) - pre(rk);\n        }\n    }\n    for (int i = 0; i < q; ++i) out << ans[i] << \"\\n\";\n}\n";
W["hsgi-p5-kquery"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<int> a(n + 1);\n    for (int i = 1; i <= n; ++i) in >> a[i];\n    vector<int> vals = a;\n    for (int i = 0; i < q; ++i) { int x, y; in >> x >> y; vals.push_back(y); }\n    sort(vals.begin(), vals.end());\n    vals.erase(unique(vals.begin(), vals.end()), vals.end());\n    int m = vals.size();\n    vector<int> t(m + 1, 0);\n    auto add = [&](int i, int v) {\n        for (; i <= m; i += i & -i) t[i] += v;\n    };\n    auto pre = [&](int i) {\n        int s = 0;\n        for (; i > 0; i -= i & -i) s += t[i];\n        return s;\n    };\n    auto rank1 = [&](int x) {\n        return lower_bound(vals.begin(), vals.end(), x) - vals.begin() + 1;\n    };\n    vector<vector<pair<int,int>>> byI(n + 1);\n    for (int i = 0; i < q; ++i) {\n        int pos, k; in >> pos >> k;\n        byI[pos].push_back({k, i});\n    }\n    vector<long long> ans(q);\n    for (int i = 1; i <= n; ++i) {\n        add(rank1(a[i]), 1);\n        for (auto& [k, idx] : byI[i]) {\n            // near-miss: pre(rank(k)) \u0111\u1ebfm ph\u1ea7n t\u1eed \u2264 k thay v\u00ec > k \u2014\n            // \u0111\u00e1p \u00e1n b\u1ecb \u0111\u1ea3o (b\u00e1o ph\u1ea7n nh\u1ecf h\u01a1n/kh\u00f4ng v\u01b0\u1ee3t k)\n            ans[idx] = pre(rank1(k));\n        }\n    }\n    for (int i = 0; i < q; ++i) out << ans[i] << \"\\n\";\n}\n";
R["hsgi-cp-m5-chaos"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<int> s(n);\n    for (auto& x : s) in >> x;\n    vector<int> vals = s;\n    sort(vals.begin(), vals.end());\n    vals.erase(unique(vals.begin(), vals.end()), vals.end());\n    int m = vals.size();\n    vector<int> t(m + 1, 0);\n    auto add = [&](int i) {\n        for (; i <= m; i += i & -i) t[i] += 1;\n    };\n    auto pre = [&](int i) {\n        int s = 0;\n        for (; i > 0; i -= i & -i) s += t[i];\n        return s;\n    };\n    long long total = 0;\n    for (int j = 0; j < n; ++j) {\n        int r = lower_bound(vals.begin(), vals.end(), s[j]) - vals.begin() + 1;\n        total += (long long)j - pre(r);   // s\u1ed1 ng\u01b0\u1eddi tr\u01b0\u1edbc GI\u1eeeA cao h\u01a1n\n        add(r);\n    }\n    out << total << \"\\n\";\n}\n";
W["hsgi-cp-m5-chaos"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<int> s(n);\n    for (auto& x : s) in >> x;\n    vector<int> vals = s;\n    sort(vals.begin(), vals.end());\n    vals.erase(unique(vals.begin(), vals.end()), vals.end());\n    int m = vals.size();\n    vector<int> t(m + 1, 0);\n    auto add = [&](int i) {\n        for (; i <= m; i += i & -i) t[i] += 1;\n    };\n    auto pre = [&](int i) {\n        int s = 0;\n        for (; i > 0; i -= i & -i) s += t[i];\n        return s;\n    };\n    // near-miss: THU\u1eacT TO\u00c1N \u0111\u00fang, NG\u00c2N S\u00c1CH \u0111\u00fang \u2014 nh\u01b0ng total l\u00e0 int:\n    // n(n\u22121)/2 = 19999900000 v\u01b0\u1ee3t 2^31 \u2192 tr\u00e0n s\u1ed1 tr\u00ean test l\u1edbn nh\u1ea5t\n    int total = 0;\n    for (int j = 0; j < n; ++j) {\n        int r = lower_bound(vals.begin(), vals.end(), s[j]) - vals.begin() + 1;\n        total += j - pre(r);\n        add(r);\n    }\n    out << total << \"\\n\";\n}\n";
R["hsgi-p6-point"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <map>\n#include <cmath>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<long long> t(4 * n, 0);\n    // iterative-friendly recursive build over explicit values\n    vector<long long> a(n + 1);\n    for (int i = 1; i <= n; ++i) in >> a[i];\n    // build iteratively bottom-up (size = next pow2 not needed for sum):\n    // use classic recursive lambda build on 4n tree\n    auto bld = [&](auto&& self, int v, int lo, int hi) -> void {\n        if (lo == hi) { t[v] = a[lo]; return; }\n        int mid = (lo + hi) / 2;\n        self(self, 2*v, lo, mid);\n        self(self, 2*v+1, mid+1, hi);\n        t[v] = t[2*v] + t[2*v+1];\n    };\n    bld(bld, 1, 1, n);\n    auto upd = [&](auto&& self, int v, int lo, int hi, int i, long long x) -> void {\n        if (lo == hi) { t[v] = x; return; }\n        int mid = (lo + hi) / 2;\n        if (i <= mid) self(self, 2*v, lo, mid, i, x);\n        else self(self, 2*v+1, mid+1, hi, i, x);\n        t[v] = t[2*v] + t[2*v+1];\n    };\n    auto qry = [&](auto&& self, int v, int lo, int hi, int l, int r) -> long long {\n        if (r < lo || hi < l) return 0;\n        if (l <= lo && hi <= r) return t[v];\n        int mid = (lo + hi) / 2;\n        return self(self, 2*v, lo, mid, l, r) + self(self, 2*v+1, mid+1, hi, l, r);\n    };\n    while (q--) {\n        int tp; in >> tp;\n        if (tp == 1) { int i; long long x; in >> i >> x; upd(upd, 1, 1, n, i, x); }\n        else { int l, r; in >> l >> r; out << qry(qry, 1, 1, n, l, r) << \"\\n\"; }\n    }\n}\n";
W["hsgi-p6-point"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <map>\n#include <cmath>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<long long> t(4 * n, 0);\n    vector<long long> a(n + 1);\n    for (int i = 1; i <= n; ++i) in >> a[i];\n    auto bld = [&](auto&& self, int v, int lo, int hi) -> void {\n        if (lo == hi) { t[v] = a[lo]; return; }\n        int mid = (lo + hi) / 2;\n        self(self, 2*v, lo, mid);\n        self(self, 2*v+1, mid+1, hi);\n        t[v] = t[2*v] + t[2*v+1];\n    };\n    bld(bld, 1, 1, n);\n    // near-miss: query tr\u1ea3 max thay v\u00ec t\u1ed5ng \u2014 ng\u01b0\u1eddi h\u1ecdc nh\u1ea7m ph\u00e9p h\u1ee3p khi\n    // ch\u00e9p b\u1ed9 khung b\u00e0i max (l\u1ed7i gh\u00e9p b\u1ed9 khung kinh \u0111i\u1ec3n)\n    auto upd = [&](auto&& self, int v, int lo, int hi, int i, long long x) -> void {\n        if (lo == hi) { t[v] = x; return; }\n        int mid = (lo + hi) / 2;\n        if (i <= mid) self(self, 2*v, lo, mid, i, x);\n        else self(self, 2*v+1, mid+1, hi, i, x);\n        t[v] = t[2*v] + t[2*v+1];\n    };\n    auto qry = [&](auto&& self, int v, int lo, int hi, int l, int r) -> long long {\n        if (r < lo || hi < l) return 0;\n        if (l <= lo && hi <= r) return t[v];\n        int mid = (lo + hi) / 2;\n        return max(self(self, 2*v, lo, mid, l, r), self(self, 2*v+1, mid+1, hi, l, r));\n    };\n    while (q--) {\n        int tp; in >> tp;\n        if (tp == 1) { int i; long long x; in >> i >> x; upd(upd, 1, 1, n, i, x); }\n        else { int l, r; in >> l >> r; out << qry(qry, 1, 1, n, l, r) << \"\\n\"; }\n    }\n}\n";
R["hsgi-p6-maxsum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <map>\n#include <cmath>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<long long> t(4 * n, LLONG_MIN);\n    vector<long long> a(n + 1);\n    for (int i = 1; i <= n; ++i) in >> a[i];\n    auto bld = [&](auto&& self, int v, int lo, int hi) -> void {\n        if (lo == hi) { t[v] = a[lo]; return; }\n        int mid = (lo + hi) / 2;\n        self(self, 2*v, lo, mid);\n        self(self, 2*v+1, mid+1, hi);\n        t[v] = max(t[2*v], t[2*v+1]);\n    };\n    bld(bld, 1, 1, n);\n    auto upd = [&](auto&& self, int v, int lo, int hi, int i, long long x) -> void {\n        if (lo == hi) { t[v] = x; return; }\n        int mid = (lo + hi) / 2;\n        if (i <= mid) self(self, 2*v, lo, mid, i, x);\n        else self(self, 2*v+1, mid+1, hi, i, x);\n        t[v] = max(t[2*v], t[2*v+1]);\n    };\n    auto qry = [&](auto&& self, int v, int lo, int hi, int l, int r) -> long long {\n        if (r < lo || hi < l) return LLONG_MIN;\n        if (l <= lo && hi <= r) return t[v];\n        int mid = (lo + hi) / 2;\n        return max(self(self, 2*v, lo, mid, l, r), self(self, 2*v+1, mid+1, hi, l, r));\n    };\n    while (q--) {\n        int tp; in >> tp;\n        if (tp == 1) { int i; long long x; in >> i >> x; upd(upd, 1, 1, n, i, x); }\n        else { int l, r; in >> l >> r; out << qry(qry, 1, 1, n, l, r) << \"\\n\"; }\n    }\n}\n";
W["hsgi-p6-maxsum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <map>\n#include <cmath>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<long long> t(4 * n, 0);\n    // near-miss: kh\u1edfi t\u1ea1o v\u00e0 identity l\u00e0 0 thay v\u00ec \u2212\u221e \u2014 d\u00e3y to\u00e0n \u00e2m tr\u1ea3 0 sai\n    vector<long long> a(n + 1);\n    for (int i = 1; i <= n; ++i) in >> a[i];\n    auto bld = [&](auto&& self, int v, int lo, int hi) -> void {\n        if (lo == hi) { t[v] = a[lo]; return; }\n        int mid = (lo + hi) / 2;\n        self(self, 2*v, lo, mid);\n        self(self, 2*v+1, mid+1, hi);\n        t[v] = max(t[2*v], t[2*v+1]);\n    };\n    bld(bld, 1, 1, n);\n    auto upd = [&](auto&& self, int v, int lo, int hi, int i, long long x) -> void {\n        if (lo == hi) { t[v] = x; return; }\n        int mid = (lo + hi) / 2;\n        if (i <= mid) self(self, 2*v, lo, mid, i, x);\n        else self(self, 2*v+1, mid+1, hi, i, x);\n        t[v] = max(t[2*v], t[2*v+1]);\n    };\n    auto qry = [&](auto&& self, int v, int lo, int hi, int l, int r) -> long long {\n        if (r < lo || hi < l) return 0;\n        if (l <= lo && hi <= r) return t[v];\n        int mid = (lo + hi) / 2;\n        return max(self(self, 2*v, lo, mid, l, r), self(self, 2*v+1, mid+1, hi, l, r));\n    };\n    while (q--) {\n        int tp; in >> tp;\n        if (tp == 1) { int i; long long x; in >> i >> x; upd(upd, 1, 1, n, i, x); }\n        else { int l, r; in >> l >> r; out << qry(qry, 1, 1, n, l, r) << \"\\n\"; }\n    }\n}\n";
