R["hsgi-p7-components"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <array>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<int> par(n + 1), sz_(n + 1, 1);\n    for (int i = 1; i <= n; ++i) par[i] = i;\n    auto find = [&](int x) {\n        while (par[x] != x) { par[x] = par[par[x]]; x = par[x]; }\n        return x;\n    };\n    int comps = n;\n    while (m--) {\n        int u, v; in >> u >> v;\n        u = find(u); v = find(v);\n        if (u != v) {\n            if (sz_[u] < sz_[v]) swap(u, v);\n            par[v] = u; sz_[u] += sz_[v];\n            --comps;\n        }\n        out << comps << \"\\n\";\n    }\n}\n";
W["hsgi-p7-components"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <array>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<int> par(n + 1), sz_(n + 1, 1);\n    for (int i = 1; i <= n; ++i) par[i] = i;\n    auto find = [&](int x) {\n        while (par[x] != x) { par[x] = par[par[x]]; x = par[x]; }\n        return x;\n    };\n    // near-miss: gi\u1ea3m b\u1ed9 \u0111\u1ebfm M\u1eccI l\u1ea7n g\u1ecdi, k\u1ec3 c\u1ea3 khi u, v \u0111\u00e3 c\u00f9ng v\u00f9ng \u2014\n    // qu\u00ean nh\u00e1nh unite tr\u1ea3 FALSE c\u1ee7a b\u00e0i 7.1\n    int comps = n;\n    while (m--) {\n        int u, v; in >> u >> v;\n        u = find(u); v = find(v);\n        if (sz_[u] < sz_[v]) swap(u, v);\n        par[v] = u; sz_[u] += sz_[v];\n        --comps;\n        out << comps << \"\\n\";\n    }\n}\n";
R["hsgi-p7-mst-kruskal"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <array>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<array<long long,3>> e(m);\n    for (auto& [w, u, v] : e) in >> u >> v >> w;\n    sort(e.begin(), e.end());\n    vector<int> par(n + 1), sz_(n + 1, 1);\n    for (int i = 1; i <= n; ++i) par[i] = i;\n    auto find = [&](int x) {\n        while (par[x] != x) { par[x] = par[par[x]]; x = par[x]; }\n        return x;\n    };\n    long long total = 0; int taken = 0;\n    for (auto& [w, u, v] : e) {\n        int a = find(u), b = find(v);\n        if (a != b) {\n            if (sz_[a] < sz_[b]) swap(a, b);\n            par[b] = a; sz_[a] += sz_[b];\n            total += w; ++taken;\n            if (taken == n - 1) break;\n        }\n    }\n    out << total << \"\\n\";\n}\n";
W["hsgi-p7-mst-kruskal"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <array>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<array<long long,3>> e(m);\n    for (auto& [w, u, v] : e) in >> u >> v >> w;\n    sort(e.begin(), e.end());\n    // near-miss: c\u1ed9ng (n\u22121) c\u1ea1nh R\u1eba NH\u1ea4T b\u1ea5t k\u1ec3 ch\u00fang c\u00f3 n\u1ed1i m\u1ecdi \u0111\u1ec9nh hay\n    // kh\u00f4ng \u2014 c\u00e1c c\u1ea1nh r\u1ebb trong chu tr\u00ecnh b\u1ecb \u0111\u1ebfm nhi\u1ec1u l\u1ea7n, c\u1ea1nh \u0111\u1eaft b\u1eaft\n    // bu\u1ed9c b\u1ecb b\u1ecf s\u00f3t\n    long long total = 0;\n    for (int i = 0; i < n - 1 && i < m; ++i) total += e[i][0];\n    out << total << \"\\n\";\n}\n";
R["hsgi-p7-redundant"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <array>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<int> par(n + 1), sz_(n + 1, 1);\n    for (int i = 1; i <= n; ++i) par[i] = i;\n    auto find = [&](int x) {\n        while (par[x] != x) { par[x] = par[par[x]]; x = par[x]; }\n        return x;\n    };\n    while (m--) {\n        int u, v; in >> u >> v;\n        int a = find(u), b = find(v);\n        if (a == b) out << \"YES\" << \"\\n\";\n        else {\n            if (sz_[a] < sz_[b]) swap(a, b);\n            par[b] = a; sz_[a] += sz_[b];\n            out << \"NO\" << \"\\n\";\n        }\n    }\n}\n";
W["hsgi-p7-redundant"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <array>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<vector<int>> adj(n + 1);\n    // near-miss: \u0111o\u00e1n chu tr\u00ecnh b\u1eb1ng K\u1ec0 tr\u1ef1c ti\u1ebfp \u2014 in YES n\u1ebfu u, v \u0111\u00e3 l\u00e0\n    // h\u00e0ng x\u00f3m c\u1ee7a nhau; b\u1ecf s\u00f3t m\u1ecdi chu tr\u00ecnh qua \u0111\u1ec9nh trung gian\n    while (m--) {\n        int u, v; in >> u >> v;\n        bool dup = false;\n        for (int x : adj[u]) if (x == v) { dup = true; break; }\n        out << (dup ? \"YES\" : \"NO\") << \"\\n\";\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n}\n";
R["hsgi-p7-bottleneck"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <array>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m, q; in >> n >> m >> q;\n    vector<array<long long,3>> e(m);\n    for (auto& [w, u, v] : e) in >> u >> v >> w;\n    sort(e.begin(), e.end());\n    vector<int> par(n + 1), sz_(n + 1, 1);\n    for (int i = 1; i <= n; ++i) par[i] = i;\n    auto find = [&](int x) {\n        while (par[x] != x) { par[x] = par[par[x]]; x = par[x]; }\n        return x;\n    };\n    vector<long long> ans(q, -1);\n    vector<vector<pair<int,int>>> pend(n + 1);   // g\u1ed1c -> (\u0111\u1ea7u kia, ch\u1ec9 s\u1ed1 truy v\u1ea5n)\n    for (int j = 0; j < q; ++j) {\n        int u, v; in >> u >> v;\n        if (u == v) ans[j] = 0;\n        else { pend[u].push_back({v, j}); pend[v].push_back({u, j}); }\n    }\n    for (auto& [w, u, v] : e) {\n        int a = find(u), b = find(v);\n        if (a == b) continue;\n        if (sz_[a] < sz_[b]) { swap(a, b); }\n        par[b] = a; sz_[a] += sz_[b];\n        if (pend[b].size() > pend[a].size()) swap(pend[a], pend[b]);\n        vector<pair<int,int>> keep;\n        for (auto& [v2, j] : pend[b]) {\n            if (find(v2) == a) ans[j] = w;       // l\u1ea7n \u0111\u1ea7u nh\u1eadp chung \u2014 ch\u00ednh l\u00e0 bottleneck\n            else keep.push_back({v2, j});\n        }\n        for (auto& p : keep) pend[a].push_back(p);\n        pend[b].clear();\n    }\n    for (int j = 0; j < q; ++j) out << ans[j] << \"\\n\";\n}\n";
W["hsgi-p7-bottleneck"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <array>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m, q; in >> n >> m >> q;\n    vector<array<long long,3>> e(m);\n    for (auto& [w, u, v] : e) in >> u >> v >> w;\n    // near-miss: sort GI\u1ea2M d\u1ea7n v\u00e0 l\u1ea5y c\u1ea1nh \u0111\u1ea7u ti\u00ean khi\u1ebfn u, v li\u00ean th\u00f4ng \u2014\n    // t\u00ednh nh\u1ea7m \"bottleneck L\u1edaN nh\u1ea5t\" thay v\u00ec nh\u1ecf nh\u1ea5t\n    sort(e.rbegin(), e.rend());\n    while (q--) {\n        int u, v; in >> u >> v;\n        vector<int> par(n + 1);\n        for (int i = 1; i <= n; ++i) par[i] = i;\n        auto find = [&](int x) {\n            while (par[x] != x) { par[x] = par[par[x]]; x = par[x]; }\n            return x;\n        };\n        long long res = -1;\n        for (auto& [w, a, b] : e) {\n            int ra = find(a), rb = find(b);\n            if (ra != rb) par[rb] = ra;\n            if (find(u) == find(v)) { res = w; break; }\n        }\n        out << res << \"\\n\";\n    }\n}\n";
R["hsgi-p7-same-set"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <array>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<int> par(n + 1), sz_(n + 1, 1);\n    for (int i = 1; i <= n; ++i) par[i] = i;\n    auto find = [&](int x) {\n        while (par[x] != x) { par[x] = par[par[x]]; x = par[x]; }\n        return x;\n    };\n    while (q--) {\n        int tp, u, v; in >> tp >> u >> v;\n        if (tp == 1) {\n            int a = find(u), b = find(v);\n            if (a != b) {\n                if (sz_[a] < sz_[b]) swap(a, b);\n                par[b] = a; sz_[a] += sz_[b];\n            }\n        } else {\n            out << (find(u) == find(v) ? \"YES\" : \"NO\") << \"\\n\";\n        }\n    }\n}\n";
W["hsgi-p7-same-set"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <array>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<int> par(n + 1), sz_(n + 1, 1);\n    for (int i = 1; i <= n; ++i) par[i] = i;\n    auto find = [&](int x) {\n        while (par[x] != x) { par[x] = par[par[x]]; x = par[x]; }\n        return x;\n    };\n    // near-miss: so CHA TR\u1ef0C TI\u1ebeP thay v\u00ec find \u2014 hai \u0111\u1ec9nh c\u00f9ng t\u1eadp v\u1eabn\n    // NO khi cha tr\u1ef1c ti\u1ebfp kh\u00e1c nhau (union by size \u0111\u1ec3 c\u00e2y kh\u00f4ng sao ch\u00e9p)\n    while (q--) {\n        int tp, u, v; in >> tp >> u >> v;\n        if (tp == 1) {\n            int a = find(u), b = find(v);\n            if (a != b) {\n                if (sz_[a] < sz_[b]) swap(a, b);\n                par[b] = a; sz_[a] += sz_[b];\n            }\n        } else {\n            out << (par[u] == par[v] ? \"YES\" : \"NO\") << \"\\n\";\n        }\n    }\n}\n";
R["hsgi-cp-m7-rescue"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <array>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<array<long long,3>> e(m);\n    for (auto& [w, u, v] : e) in >> u >> v >> w;\n    sort(e.begin(), e.end());\n    vector<int> par(n + 1), sz_(n + 1, 1);\n    for (int i = 1; i <= n; ++i) par[i] = i;\n    auto find = [&](int x) {\n        while (par[x] != x) { par[x] = par[par[x]]; x = par[x]; }\n        return x;\n    };\n    long long total = 0; int taken = 0;\n    for (auto& [w, u, v] : e) {\n        int a = find(u), b = find(v);\n        if (a != b) {\n            if (sz_[a] < sz_[b]) swap(a, b);\n            par[b] = a; sz_[a] += sz_[b];\n            total += w; ++taken;\n            if (taken == n - 1) break;\n        }\n    }\n    out << (taken == n - 1 ? total : -1) << \"\\n\";\n}\n";
W["hsgi-cp-m7-rescue"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <array>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<array<long long,3>> e(m);\n    for (auto& [w, u, v] : e) in >> u >> v >> w;\n    sort(e.begin(), e.end());\n    // near-miss: c\u1ed9ng (n\u22121) c\u1ea1nh r\u1ebb nh\u1ea5t m\u00e0 KH\u00d4NG ki\u1ec3m tra li\u00ean th\u00f4ng \u2014\n    // c\u1ea1nh r\u1ebb trong chu tr\u00ecnh b\u1ecb c\u1ed9ng nhi\u1ec1u l\u1ea7n, c\u1ea1nh \u0111\u1eaft b\u1eaft bu\u1ed9c b\u1ecb b\u1ecf,\n    // v\u00e0 \u0111\u1ed3 th\u1ecb r\u1eddi r\u1ea1c v\u1eabn in ra m\u1ed9t t\u1ed5ng v\u00f4 ngh\u0129a\n    long long total = 0;\n    for (int i = 0; i < n - 1 && i < m; ++i) total += e[i][0];\n    out << total << \"\\n\";\n}\n";
R["hsgi-p8-dijkstra-basic"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m, s; in >> n >> m >> s;\n    vector<vector<pair<int,long long>>> adj(n + 1);\n    for (int i = 0; i < m; ++i) {\n        int u, v; long long w; in >> u >> v >> w;\n        adj[u].push_back({v, w});\n    }\n    vector<long long> dist(n + 1, LLONG_MAX);\n    dist[s] = 0;\n    priority_queue<pair<long long,int>,\n                   vector<pair<long long,int>>,\n                   greater<>> pq;\n    pq.push({0, s});\n    while (!pq.empty()) {\n        auto [d, u] = pq.top(); pq.pop();\n        if (d != dist[u]) continue;\n        for (auto& [v, w] : adj[u])\n            if (d + w < dist[v]) {\n                dist[v] = d + w;\n                pq.push({dist[v], v});\n            }\n    }\n    for (int i = 1; i <= n; ++i)\n        out << (dist[i] == LLONG_MAX ? -1LL : dist[i]) << \"\\n\";\n}\n";
W["hsgi-p8-dijkstra-basic"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m, s; in >> n >> m >> s;\n    vector<vector<pair<int,long long>>> adj(n + 1);\n    for (int i = 0; i < m; ++i) {\n        int u, v; long long w; in >> u >> v >> w;\n        adj[u].push_back({v, w});\n    }\n    // near-miss: KH\u00d4NG kh\u1edfi t\u1ea1o dist[s] = 0 \u2014 ngu\u1ed3n v\u1eabn LLONG_MAX, m\u1ecdi\n    // n\u1edbi l\u1ecfng t\u1eeb ngu\u1ed3n b\u1ecb v\u00f4 hi\u1ec7u, m\u1ecdi th\u00e0nh ph\u1ed1 (k\u1ec3 c\u1ea3 ngu\u1ed3n) in \u22121\n    vector<long long> dist(n + 1, LLONG_MAX);\n    priority_queue<pair<long long,int>,\n                   vector<pair<long long,int>>,\n                   greater<>> pq;\n    pq.push({0, s});\n    while (!pq.empty()) {\n        auto [d, u] = pq.top(); pq.pop();\n        if (d != dist[u]) continue;\n        for (auto& [v, w] : adj[u])\n            if (d + w < dist[v]) {\n                dist[v] = d + w;\n                pq.push({dist[v], v});\n            }\n    }\n    for (int i = 1; i <= n; ++i)\n        out << (dist[i] == LLONG_MAX ? -1LL : dist[i]) << \"\\n\";\n}\n";
R["hsgi-p8-negative-trap"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<vector<pair<int,long long>>> adj(n + 1);\n    for (int i = 0; i < m; ++i) {\n        int u, v; long long w; in >> u >> v >> w;\n        adj[u].push_back({v, w});\n    }\n    vector<long long> dist(n + 1, LLONG_MAX);\n    dist[1] = 0;\n    priority_queue<pair<long long,int>,\n                   vector<pair<long long,int>>,\n                   greater<>> pq;\n    pq.push({0, 1});\n    while (!pq.empty()) {\n        auto [d, u] = pq.top(); pq.pop();\n        if (d != dist[u]) continue;\n        for (auto& [v, w] : adj[u])\n            if (d + w < dist[v]) {\n                dist[v] = d + w;\n                pq.push({dist[v], v});\n            }\n    }\n    out << (dist[n] == LLONG_MAX ? -1LL : dist[n]) << \"\\n\";\n}\n";
W["hsgi-p8-negative-trap"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    // near-miss: \u0111\u1ecdc tuy\u1ebfn M\u1ed8T CHI\u1ec0U nh\u01b0 hai chi\u1ec1u \u2014 \u0111\u1ed3 th\u1ecb trong \u0111\u1ec1 l\u00e0\n    // C\u00d3 H\u01af\u1edaNG; th\u00eam c\u1ea1nh ng\u01b0\u1ee3c t\u1ea1o ra \u0111\u01b0\u1eddng \u0111i kh\u00f4ng t\u1ed3n t\u1ea1i\n    vector<vector<pair<int,long long>>> adj(n + 1);\n    for (int i = 0; i < m; ++i) {\n        int u, v; long long w; in >> u >> v >> w;\n        adj[u].push_back({v, w});\n        adj[v].push_back({u, w});\n    }\n    vector<long long> dist(n + 1, LLONG_MAX);\n    dist[1] = 0;\n    priority_queue<pair<long long,int>,\n                   vector<pair<long long,int>>,\n                   greater<>> pq;\n    pq.push({0, 1});\n    while (!pq.empty()) {\n        auto [d, u] = pq.top(); pq.pop();\n        if (d != dist[u]) continue;\n        for (auto& [v, w] : adj[u])\n            if (d + w < dist[v]) {\n                dist[v] = d + w;\n                pq.push({dist[v], v});\n            }\n    }\n    out << (dist[n] == LLONG_MAX ? -1LL : dist[n]) << \"\\n\";\n}\n";
R["hsgi-p8-zero-one"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m, s; in >> n >> m >> s;\n    vector<vector<pair<int,int>>> adj(n + 1);\n    for (int i = 0; i < m; ++i) {\n        int u, v, c; in >> u >> v >> c;\n        adj[u].push_back({v, c});\n    }\n    vector<int> d(n + 1, INT_MAX);\n    d[s] = 0;\n    deque<pair<int,int>> dq;\n    dq.push_back({0, s});\n    while (!dq.empty()) {\n        auto [du, u] = dq.front(); dq.pop_front();\n        if (du != d[u]) continue;\n        for (auto& [v, w] : adj[u]) {\n            int nd = du + w;\n            if (nd < d[v]) {\n                d[v] = nd;\n                if (w == 0) dq.push_front({nd, v});\n                else        dq.push_back({nd, v});\n            }\n        }\n    }\n    for (int i = 1; i <= n; ++i)\n        out << (d[i] == INT_MAX ? -1 : d[i]) << \"\\n\";\n}\n";
W["hsgi-p8-zero-one"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m, s; in >> n >> m >> s;\n    vector<vector<pair<int,int>>> adj(n + 1);\n    for (int i = 0; i < m; ++i) {\n        int u, v, c; in >> u >> v >> c;\n        adj[u].push_back({v, c});\n    }\n    // near-miss: kh\u00f3a v\u0129nh vi\u1ec5n ngay l\u1ea7n \u0111\u1ea7u PH\u00c1T HI\u1ec6N (nh\u01b0 BFS thu\u1ea7n) \u2014\n    // ph\u00f2ng ph\u00e1t hi\u1ec7n qua c\u1eeda ph\u00ed 1 kh\u00f4ng bao gi\u1edd \u0111\u01b0\u1ee3c c\u1ea3i thi\u1ec7n b\u1edfi\n    // \u0111\u01b0\u1eddng mi\u1ec5n ph\u00ed \u0111\u1ebfn sau\n    vector<int> d(n + 1, INT_MAX);\n    d[s] = 0;\n    deque<pair<int,int>> dq;\n    dq.push_back({0, s});\n    while (!dq.empty()) {\n        auto [du, u] = dq.front(); dq.pop_front();\n        for (auto& [v, w] : adj[u]) {\n            if (d[v] != INT_MAX) continue;\n            d[v] = du + w;\n            if (w == 0) dq.push_front({d[v], v});\n            else        dq.push_back({d[v], v});\n        }\n    }\n    for (int i = 1; i <= n; ++i)\n        out << (d[i] == INT_MAX ? -1 : d[i]) << \"\\n\";\n}\n";
R["hsgi-p8-bfs-plain"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m, s; in >> n >> m >> s;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < m; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    vector<int> d(n + 1, -1);\n    queue<int> bq;\n    d[s] = 0;\n    bq.push(s);\n    while (!bq.empty()) {\n        int u = bq.front(); bq.pop();\n        for (int v : adj[u])\n            if (d[v] == -1) {\n                d[v] = d[u] + 1;\n                bq.push(v);\n            }\n    }\n    for (int i = 1; i <= n; ++i) out << d[i] << \"\\n\";\n}\n";
W["hsgi-p8-bfs-plain"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m, s; in >> n >> m >> s;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < m; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    // near-miss: m\u1ecdi c\u1eeda \u0111\u1ec1u MI\u1ec4N PH\u00cd (d[v] = d[u]) \u2014 qu\u00ean \u0111\u1ebfm b\u01b0\u1edbc;\n    // m\u1ecdi ph\u00f2ng n\u1ed1i th\u00f4ng v\u1edbi ngu\u1ed3n \u0111\u1ec1u in 0\n    vector<int> d(n + 1, -1);\n    queue<int> bq;\n    d[s] = 0;\n    bq.push(s);\n    while (!bq.empty()) {\n        int u = bq.front(); bq.pop();\n        for (int v : adj[u])\n            if (d[v] == -1) {\n                d[v] = d[u];\n                bq.push(v);\n            }\n    }\n    for (int i = 1; i <= n; ++i) out << d[i] << \"\\n\";\n}\n";
R["hsgi-p8-flip"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m, s; in >> n >> m >> s;\n    vector<vector<pair<int,int>>> adj(n + 1);\n    for (int i = 0; i < m; ++i) {\n        int u, v, c; in >> u >> v >> c;\n        adj[u].push_back({v, c});\n    }\n    vector<int> d(n + 1, INT_MAX);\n    d[s] = 0;\n    deque<pair<int,int>> dq;\n    dq.push_back({0, s});\n    while (!dq.empty()) {\n        auto [du, u] = dq.front(); dq.pop_front();\n        if (du != d[u]) continue;\n        for (auto& [v, w] : adj[u]) {\n            int nd = du + w;\n            if (nd < d[v]) {\n                d[v] = nd;\n                if (w == 0) dq.push_front({nd, v});\n                else        dq.push_back({nd, v});\n            }\n        }\n    }\n    for (int i = 1; i <= n; ++i)\n        out << (d[i] == INT_MAX ? -1 : d[i]) << \"\\n\";\n}\n";
