R["hsgi-cp-m8-flight"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m, s; in >> n >> m >> s;\n    vector<vector<pair<int,long long>>> adj(n + 1);\n    for (int i = 0; i < m; ++i) {\n        int u, v; long long w; in >> u >> v >> w;\n        adj[u].push_back({v, w});\n    }\n    vector<long long> dist(n + 1, LLONG_MAX);\n    dist[s] = 0;\n    priority_queue<pair<long long,int>,\n                   vector<pair<long long,int>>,\n                   greater<>> pq;\n    pq.push({0, s});\n    while (!pq.empty()) {\n        auto [d, u] = pq.top(); pq.pop();\n        if (d != dist[u]) continue;\n        for (auto& [v, w] : adj[u])\n            if (d + w < dist[v]) {\n                dist[v] = d + w;\n                pq.push({dist[v], v});\n            }\n    }\n    for (int i = 1; i <= n; ++i)\n        out << (dist[i] == LLONG_MAX ? -1LL : dist[i]) << \"\\n\";\n}\n";
