R["hsgi-p9-topo-basic"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<vector<int>> adj(n + 1);\n    vector<int> deg(n + 1, 0);\n    for (int i = 0; i < m; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v);\n        ++deg[v];\n    }\n    priority_queue<int, vector<int>, greater<>> pq;\n    for (int i = 1; i <= n; ++i)\n        if (deg[i] == 0) pq.push(i);\n    vector<int> order;\n    while (!pq.empty()) {\n        int u = pq.top(); pq.pop();\n        order.push_back(u);\n        for (int v : adj[u])\n            if (--deg[v] == 0) pq.push(v);\n    }\n    if ((int)order.size() < n) { out << -1 << \"\\n\"; return; }\n    for (size_t i = 0; i < order.size(); ++i)\n        out << order[i] << \" \\n\"[i + 1 == order.size()];\n}\n";
