R["hsgi-p9-critical"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<long long> t(n + 1);\n    for (int i = 1; i <= n; ++i) in >> t[i];\n    vector<vector<int>> adj(n + 1);\n    vector<int> deg(n + 1, 0);\n    for (int i = 0; i < m; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v);\n        ++deg[v];\n    }\n    queue<int> bq;\n    for (int i = 1; i <= n; ++i)\n        if (deg[i] == 0) bq.push(i);\n    vector<long long> fin(n + 1, 0);\n    long long ans = 0;\n    while (!bq.empty()) {\n        int u = bq.front(); bq.pop();\n        fin[u] += t[u];               // c\u00f4ng \u0111o\u1ea1n u ho\u00e0n t\u1ea5t\n        if (fin[u] > ans) ans = fin[u];\n        for (int v : adj[u]) {\n            if (fin[u] > fin[v]) fin[v] = fin[u];\n            if (--deg[v] == 0) bq.push(v);\n        }\n    }\n    out << ans << \"\\n\";\n}\n";
