W["hsgi-cp-m9-prereq"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<vector<int>> adj(n + 1);\n    vector<int> deg(n + 1, 0);\n    for (int i = 0; i < m; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v);\n        ++deg[v];\n    }\n    // near-miss: queue TH\u01af\u1edcNG thay min-heap \u2014 th\u1ee9 t\u1ef1 v\u1eabn h\u1ee3p l\u1ec7 nh\u01b0ng\n    // KH\u00d4NG nh\u1ecf nh\u1ea5t theo t\u1eeb \u0111i\u1ec3n; test ch\u1ea5m t\u1eebng byte b\u1ecb tr\u01b0\u1ee3t\n    queue<int> bq;\n    for (int i = 1; i <= n; ++i)\n        if (deg[i] == 0) bq.push(i);\n    vector<int> order;\n    while (!bq.empty()) {\n        int u = bq.front(); bq.pop();\n        order.push_back(u);\n        for (int v : adj[u])\n            if (--deg[v] == 0) bq.push(v);\n    }\n    if ((int)order.size() < n) { out << -1 << \"\\n\"; return; }\n    for (size_t i = 0; i < order.size(); ++i)\n        out << order[i] << \" \\n\"[i + 1 == order.size()];\n}\n";
R["hsgi-p10-family"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < n - 1; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    vector<int> par(n + 1, 0), dep(n + 1, 0);\n    queue<int> bq;\n    bq.push(1);\n    while (!bq.empty()) {\n        int u = bq.front(); bq.pop();\n        for (int v : adj[u])\n            if (v != par[u]) {\n                par[v] = u;\n                dep[v] = dep[u] + 1;\n                bq.push(v);\n            }\n    }\n    for (int i = 1; i <= n; ++i)\n        out << par[i] << \" \" << dep[i] << \"\\n\";\n}\n";
W["hsgi-p10-family"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<vector<int>> adj(n + 1);\n    // near-miss: ch\u1ec9 l\u01b0u M\u1ed8T CHI\u1ec0U theo th\u1ee9 t\u1ef1 \u0111\u1ecdc \u2014 c\u1ea1nh \"con tr\u01b0\u1edbc,\n    // cha sau\" b\u1ecb m\u1ea5t, n\u1eeda c\u00e2y bi\u1ebfn m\u1ea5t kh\u1ecfi ph\u00e9p duy\u1ec7t\n    for (int i = 0; i < n - 1; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v);\n    }\n    vector<int> par(n + 1, 0), dep(n + 1, 0);\n    queue<int> bq;\n    bq.push(1);\n    while (!bq.empty()) {\n        int u = bq.front(); bq.pop();\n        for (int v : adj[u])\n            if (v != par[u]) {\n                par[v] = u;\n                dep[v] = dep[u] + 1;\n                bq.push(v);\n            }\n    }\n    for (int i = 1; i <= n; ++i)\n        out << par[i] << \" \" << dep[i] << \"\\n\";\n}\n";
R["hsgi-p10-subtree"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < n - 1; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    vector<int> par(n + 1, 0), order;\n    order.reserve(n);\n    queue<int> bq;\n    bq.push(1);\n    while (!bq.empty()) {\n        int u = bq.front(); bq.pop();\n        order.push_back(u);\n        for (int v : adj[u])\n            if (v != par[u]) {\n                par[v] = u;\n                bq.push(v);\n            }\n    }\n    vector<long long> sz(n + 1, 1);\n    for (int i = n - 1; i >= 0; --i) {\n        int u = order[i];\n        if (par[u]) sz[par[u]] += sz[u];\n    }\n    for (int i = 1; i <= n; ++i) out << sz[i] << \"\\n\";\n}\n";
W["hsgi-p10-subtree"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < n - 1; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    vector<int> par(n + 1, 0);\n    queue<int> bq;\n    bq.push(1);\n    while (!bq.empty()) {\n        int u = bq.front(); bq.pop();\n        for (int v : adj[u])\n            if (v != par[u]) { par[v] = u; bq.push(v); }\n    }\n    // near-miss: size = s\u1ed1 con TR\u1ef0C TI\u1ebeP (degree trong c\u00e2y g\u1ed1c) \u2014 \u0111\u1ebfm\n    // thi\u1ebfu c\u1ea3 nh\u00e1nh d\u01b0\u1edbi; tr\u00ean chu\u1ed7i m\u1ecdi node tr\u1ea3 1 thay v\u00ec n\u2212i+1\n    for (int i = 1; i <= n; ++i) out << (long long)adj[i].size() - (i != 1) << \"\\n\";\n}\n";
R["hsgi-p10-diameter"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < n - 1; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    vector<int> par(n + 1, 0), order;\n    order.reserve(n);\n    queue<int> bq;\n    bq.push(1);\n    while (!bq.empty()) {\n        int u = bq.front(); bq.pop();\n        order.push_back(u);\n        for (int v : adj[u])\n            if (v != par[u]) { par[v] = u; bq.push(v); }\n    }\n    // down[u] = chi\u1ec1u d\u00e0i nh\u00e1nh d\u00e0i nh\u1ea5t \u0111i XU\u1ed0NG t\u1eeb u\n    vector<int> down(n + 1, 0);\n    int best = 0;\n    for (int i = n - 1; i >= 0; --i) {\n        int u = order[i];\n        int d1 = 0, d2 = 0;                     // hai nh\u00e1nh t\u1ed1t nh\u1ea5t\n        for (int v : adj[u]) {\n            if (v == par[u]) continue;\n            int val = down[v] + 1;\n            if (val > d1) { d2 = d1; d1 = val; }\n            else if (val > d2) d2 = val;\n        }\n        down[u] = d1;\n        if (d1 + d2 > best) best = d1 + d2;     // \u0111\u01b0\u1eddng qua u\n    }\n    out << best << \"\\n\";\n}\n";
W["hsgi-p10-diameter"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < n - 1; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    vector<int> par(n + 1, 0), dep(n + 1, 0);\n    queue<int> bq;\n    bq.push(1);\n    while (!bq.empty()) {\n        int u = bq.front(); bq.pop();\n        for (int v : adj[u])\n            if (v != par[u]) {\n                par[v] = u;\n                dep[v] = dep[u] + 1;\n                bq.push(v);\n            }\n    }\n    // near-miss: tr\u1ea3 CHI\u1ec0U CAO t\u1eeb g\u1ed1c \u2014 \u0111\u01b0\u1eddng d\u00e0i nh\u1ea5t kh\u00f4ng qua g\u1ed1c\n    // (ch\u1ed5i hai nh\u00e1nh) b\u1ecb t\u00ednh thi\u1ebfu\n    int best = 0;\n    for (int i = 1; i <= n; ++i)\n        if (dep[i] > best) best = dep[i];\n    out << best << \"\\n\";\n}\n";
R["hsgi-p10-preorder"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < n - 1; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    for (int i = 1; i <= n; ++i)\n        sort(adj[i].begin(), adj[i].end());     // con duy\u1ec7t theo s\u1ed1 hi\u1ec7u\n    vector<int> par(n + 1, 0), order;\n    order.reserve(n);\n    // DFS b\u1eb1ng stack t\u01b0\u1eddng minh \u2014 \u0111\u01b0a con theo TH\u1ee8 T\u1ef0 NG\u01af\u1ee2C \u0111\u1ec3 pop ra\n    // \u0111\u00fang t\u0103ng d\u1ea7n\n    vector<int> st;\n    st.push_back(1);\n    while (!st.empty()) {\n        int u = st.back(); st.pop_back();\n        order.push_back(u);\n        for (auto it = adj[u].rbegin(); it != adj[u].rend(); ++it)\n            if (*it != par[u]) {\n                par[*it] = u;\n                st.push_back(*it);\n            }\n    }\n    for (size_t i = 0; i < order.size(); ++i)\n        out << order[i] << \" \\n\"[i + 1 == order.size()];\n}\n";
W["hsgi-p10-preorder"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < n - 1; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    for (int i = 1; i <= n; ++i)\n        sort(adj[i].begin(), adj[i].end());\n    // near-miss: DUY\u1ec6T T\u1ea6NG (BFS) thay v\u00ec pre-order \u2014 \u0111\u00fang tr\u00ean sao,\n    // sai ngay khi c\u00e2y c\u00f3 \u0111\u1ed9 s\u00e2u 2 tr\u1edf l\u00ean\n    vector<int> par(n + 1, 0), order;\n    order.reserve(n);\n    queue<int> bq;\n    bq.push(1);\n    while (!bq.empty()) {\n        int u = bq.front(); bq.pop();\n        order.push_back(u);\n        for (int v : adj[u])\n            if (v != par[u]) { par[v] = u; bq.push(v); }\n    }\n    for (size_t i = 0; i < order.size(); ++i)\n        out << order[i] << \" \\n\"[i + 1 == order.size()];\n}\n";
R["hsgi-p10-weightpath"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> w(n + 1);\n    for (int i = 1; i <= n; ++i) in >> w[i];\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < n - 1; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    vector<int> par(n + 1, 0), order;\n    order.reserve(n);\n    queue<int> bq;\n    bq.push(1);\n    while (!bq.empty()) {\n        int u = bq.front(); bq.pop();\n        order.push_back(u);\n        for (int v : adj[u])\n            if (v != par[u]) { par[v] = u; bq.push(v); }\n    }\n    // down[u] = w[u] + nh\u00e1nh con t\u1ed1t nh\u1ea5t (ho\u1eb7c ch\u1ec9 w[u] n\u1ebfu m\u1ecdi nh\u00e1nh k\u00e9m)\n    vector<long long> down(n + 1, 0);\n    long long best = 0;\n    for (int i = n - 1; i >= 0; --i) {\n        int u = order[i];\n        long long d1 = 0, d2 = 0;               // hai nh\u00e1nh t\u1ed1t nh\u1ea5t (\u2265 0)\n        for (int v : adj[u]) {\n            if (v == par[u]) continue;\n            long long val = down[v];\n            if (val > d1) { d2 = d1; d1 = val; }\n            else if (val > d2) d2 = val;\n        }\n        down[u] = w[u] + d1;\n        best = max(best, w[u] + d1 + d2);       // \u0111\u01b0\u1eddng qua u\n    }\n    out << best << \"\\n\";\n}\n";
W["hsgi-p10-weightpath"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> w(n + 1);\n    for (int i = 1; i <= n; ++i) in >> w[i];\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < n - 1; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    vector<int> par(n + 1, 0), order;\n    order.reserve(n);\n    queue<int> bq;\n    bq.push(1);\n    while (!bq.empty()) {\n        int u = bq.front(); bq.pop();\n        order.push_back(u);\n        for (int v : adj[u])\n            if (v != par[u]) { par[v] = u; bq.push(v); }\n    }\n    // near-miss: ch\u1ec9 x\u00e9t \u0111\u01b0\u1eddng T\u1eea G\u1ed0C XU\u1ed0NG L\u00c1 (m\u1ed9t nh\u00e1nh) \u2014 \u0111\u01b0\u1eddng g\u1eadp\n    // qua g\u1ed1c hai nh\u00e1nh n\u1eb7ng b\u1ecb b\u1ecf; tr\u00ean \"hai nh\u00e1nh 10\" tr\u1ea3 21 thay v\u00ec 41\n    vector<long long> down(n + 1, 0);\n    long long best = 0;\n    for (int i = n - 1; i >= 0; --i) {\n        int u = order[i];\n        long long bestChild = 0;\n        for (int v : adj[u]) {\n            if (v == par[u]) continue;\n            bestChild = max(bestChild, down[v]);\n        }\n        down[u] = w[u] + bestChild;\n        best = max(best, down[u]);\n    }\n    out << best << \"\\n\";\n}\n";
R["hsgi-cp-m10-cable"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    if (n == 1) { out << 0 << \"\\n\"; return; }\n    vector<long long> wv(n + 1, 0);\n    vector<vector<array<long long,2>>> adj(n + 1);   // (\u0111\u1ec9nh, tr\u1ecdng s\u1ed1)\n    for (int i = 0; i < n - 1; ++i) {\n        int u, v; long long w; in >> u >> v >> w;\n        adj[u].push_back({v, w});\n        adj[v].push_back({u, w});\n    }\n    vector<int> par(n + 1, 0), order;\n    order.reserve(n);\n    queue<int> bq;\n    bq.push(1);\n    while (!bq.empty()) {\n        int u = bq.front(); bq.pop();\n        order.push_back(u);\n        for (auto& [v, w] : adj[u])\n            if (v != par[u]) { par[v] = u; bq.push(v); }\n    }\n    vector<long long> down(n + 1, 0);\n    long long best = 0;\n    for (int i = n - 1; i >= 0; --i) {\n        int u = order[i];\n        long long d1 = 0, d2 = 0;\n        for (auto& [v, w] : adj[u]) {\n            if (v == par[u]) continue;\n            long long val = down[v] + w;\n            if (val > d1) { d2 = d1; d1 = val; }\n            else if (val > d2) d2 = val;\n        }\n        down[u] = d1;\n        best = max(best, d1 + d2);\n    }\n    out << best << \"\\n\";\n}\n";
W["hsgi-cp-m10-cable"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    if (n == 1) { out << 0 << \"\\n\"; return; }\n    vector<vector<array<long long,2>>> adj(n + 1);\n    for (int i = 0; i < n - 1; ++i) {\n        int u, v; long long w; in >> u >> v >> w;\n        adj[u].push_back({v, w});\n        adj[v].push_back({u, w});\n    }\n    vector<int> par(n + 1, 0), order;\n    order.reserve(n);\n    queue<int> bq;\n    bq.push(1);\n    while (!bq.empty()) {\n        int u = bq.front(); bq.pop();\n        order.push_back(u);\n        for (auto& [v, w] : adj[u])\n            if (v != par[u]) { par[v] = u; bq.push(v); }\n    }\n    // near-miss: CHI\u1ec0U CAO C\u00d3 TR\u1eccNG S\u1ed0 t\u1eeb g\u1ed1c (m\u1ed9t nh\u00e1nh) thay v\u00ec d1 + d2 \u2014\n    // \u0111\u01b0\u1eddng g\u1eadp qua g\u1ed1c hai nh\u00e1nh n\u1eb7ng b\u1ecb t\u00ednh thi\u1ebfu tr\u00ean c\u00e2y ch\u1ed5i\n    vector<long long> down(n + 1, 0);\n    long long best = 0;\n    for (int i = n - 1; i >= 0; --i) {\n        int u = order[i];\n        long long bestChild = 0;\n        for (auto& [v, w] : adj[u]) {\n            if (v == par[u]) continue;\n            bestChild = max(bestChild, down[v] + w);\n        }\n        down[u] = bestChild;\n        best = max(best, down[u]);\n    }\n    out << best << \"\\n\";\n}\n";
R["hsgi-p11-lis"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    vector<long long> tails;\n    for (int i = 0; i < n; ++i) {\n        auto it = lower_bound(tails.begin(), tails.end(), a[i]);\n        if (it == tails.end()) tails.push_back(a[i]);\n        else *it = a[i];\n    }\n    out << tails.size() << \"\\n\";\n}\n";
W["hsgi-p11-lis"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    // near-miss: O(n\u00b2) \u0111\u00fang k\u1ebft qu\u1ea3 nh\u01b0ng QU\u00c1 H\u1ea0N tr\u00ean n = 100 000 \u2014\n    // \u0111\u00fang gi\u1edbi h\u1ea1n \"k\u1ef9 thu\u1eadt\" m\u00e0 module d\u1ea1y\n    vector<int> dp(n, 1);\n    int best = 0;\n    for (int i = 0; i < n; ++i) {\n        for (int j = 0; j < i; ++j)\n            if (a[j] < a[i]) dp[i] = max(dp[i], dp[j] + 1);\n        best = max(best, dp[i]);\n    }\n    out << best << \"\\n\";\n}\n";
R["hsgi-p11-kadane"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    long long best = a[0], cur = a[0];\n    for (int i = 1; i < n; ++i) {\n        cur = max(a[i], cur + a[i]);\n        best = max(best, cur);\n    }\n    out << best << \"\\n\";\n}\n";
W["hsgi-p11-kadane"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    long long best = 0, cur = 0;   // near-miss: kh\u1edfi t\u1ea1o 0 \u2014 to\u00e0n \u00e2m\n    // th\u00ec tr\u1ea3 0 thay v\u00ec ph\u1ea7n t\u1eed \u00edt \u00e2m nh\u1ea5t (\u0111o\u1ea1n ph\u1ea3i KH\u00d4NG R\u1ed6NG)\n    for (int i = 0; i < n; ++i) {\n        cur = max(a[i], cur + a[i]);\n        best = max(best, cur);\n    }\n    out << best << \"\\n\";\n}\n";
R["hsgi-p11-lcs"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string a, b; in >> a >> b;\n    int n = a.size(), m = b.size();\n    vector<long long> prev(m + 1, 0), cur(m + 1, 0);\n    for (int i = 1; i <= n; ++i) {\n        for (int j = 1; j <= m; ++j) {\n            if (a[i-1] == b[j-1]) cur[j] = prev[j-1] + 1;\n            else cur[j] = max(prev[j], cur[j-1]);\n        }\n        swap(prev, cur);\n    }\n    out << prev[m] << \"\\n\";\n}\n";
W["hsgi-p11-lcs"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string a, b; in >> a >> b;\n    int n = a.size(), m = b.size();\n    // near-miss: cu\u1ed9n h\u00e0ng nh\u01b0ng QU\u00caN swap \u2014 prev kh\u00f4ng bao gi\u1edd nh\u1eadn k\u1ebft\n    // qu\u1ea3 h\u00e0ng tr\u01b0\u1edbc, m\u1ecdi dp t\u00ednh tr\u00ean prev to\u00e0n 0 \u2192 lu\u00f4n in 0\n    vector<long long> prev(m + 1, 0), cur(m + 1, 0);\n    for (int i = 1; i <= n; ++i) {\n        for (int j = 1; j <= m; ++j) {\n            if (a[i-1] == b[j-1]) cur[j] = prev[j-1] + 1;\n            else cur[j] = max(prev[j], cur[j-1]);\n        }\n    }\n    out << cur[m] << \"\\n\";\n}\n";
R["hsgi-p11-liscount"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    const long long MOD = 1000000007;\n    vector<long long> dp(n, 1), cnt(n, 1);\n    long long best = 1, total = 0;\n    for (int i = 0; i < n; ++i) {\n        for (int j = 0; j < i; ++j)\n            if (a[j] < a[i]) {\n                if (dp[j] + 1 > dp[i]) { dp[i] = dp[j] + 1; cnt[i] = cnt[j]; }\n                else if (dp[j] + 1 == dp[i]) cnt[i] = (cnt[i] + cnt[j]) % MOD;\n            }\n        if (dp[i] > best) best = dp[i];\n    }\n    for (int i = 0; i < n; ++i)\n        if (dp[i] == best) total = (total + cnt[i]) % MOD;\n    out << total << \"\\n\";\n}\n";
W["hsgi-p11-liscount"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    const long long MOD = 1000000007;\n    vector<long long> dp(n, 1), cnt(n, 1);\n    long long best = 1, total = 0;\n    for (int i = 0; i < n; ++i) {\n        for (int j = 0; j < i; ++j)\n            if (a[j] < a[i]) {\n                // near-miss: KH\u00d4NG c\u1ed9ng khi b\u1eb1ng \u2014 ch\u1ec9 ghi \u0111\u00e8; c\u00e1c c\u00e1ch\n                // \u0111\u1ea1t c\u00f9ng \u0111\u1ed9 d\u00e0i b\u1ecb m\u1ea5t (test 1 3 5 4 7 tr\u1ea3 1 thay v\u00ec 2)\n                if (dp[j] + 1 > dp[i]) { dp[i] = dp[j] + 1; cnt[i] = cnt[j]; }\n            }\n        if (dp[i] > best) best = dp[i];\n    }\n    for (int i = 0; i < n; ++i)\n        if (dp[i] == best) total = (total + cnt[i]) % MOD;\n    out << total << \"\\n\";\n}\n";
R["hsgi-p11-maxrun"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    // ti\u1ec1n t\u1ed1 P[0..n]; \u0111o\u1ea1n (l, r] t\u1ed5ng \u2265 0 \u21d4 P[r] \u2265 P[l]\n    vector<long long> P(n + 1, 0);\n    for (int i = 0; i < n; ++i) P[i+1] = P[i] + a[i];\n    // prefix-minima: cand = ch\u1ec9 s\u1ed1 l sao cho P[l] < m\u1ecdi P[k] v\u1edbi l < k \u2264 n (danh s\u00e1ch P GI\u1ea2M)\n    // v\u1edbi m\u1ed7i r: nh\u1ecb ph\u00e2n cand \u0111\u1ec3 l\u1ea5y l NH\u1ece NH\u1ea4T c\u00f3 P[l] \u2264 P[r]\n    vector<int> cand;\n    for (int i = 0; i <= n; ++i) {\n        if (cand.empty() || P[cand.back()] > P[i]) cand.push_back(i);\n    }\n    int best = 0;\n    for (int r = 1; r <= n; ++r) {\n        // cand c\u00f3 P gi\u1ea3m; c\u1ea7n ph\u1ea7n t\u1eed \u0110\u1ea6U (l nh\u1ecf nh\u1ea5t) c\u00f3 P[l] \u2264 P[r]\n        int lo = 0, hi = (int)cand.size() - 1, pos = -1;\n        while (lo <= hi) {\n            int mid = (lo + hi) / 2;\n            if (P[cand[mid]] <= P[r]) { pos = cand[mid]; hi = mid - 1; }\n            else lo = mid + 1;\n        }\n        if (pos >= 0 && pos < r) best = max(best, r - pos);\n    }\n    out << best << \"\\n\";\n}\n";
W["hsgi-p11-maxrun"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    // near-miss: hai v\u00f2ng l\u1ed3ng O(n\u00b2) \u2014 \u0111\u00fang k\u1ebft qu\u1ea3, qu\u00e1 h\u1ea1n n = 200 000\n    vector<long long> P(n + 1, 0);\n    for (int i = 0; i < n; ++i) P[i+1] = P[i] + a[i];\n    int best = 0;\n    for (int r = 1; r <= n; ++r)\n        for (int l = 0; l < r; ++l)\n            if (P[l] <= P[r]) { best = max(best, r - l); break; }\n    out << best << \"\\n\";\n}\n";
R["hsgi-cp-m11-balcony"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> h(n);\n    for (auto& x : h) in >> x;\n    const long long MOD = 1000000007;\n    vector<long long> dp(n, 1), cnt(n, 1);\n    long long best = 1;\n    for (int i = 0; i < n; ++i) {\n        for (int j = 0; j < i; ++j)\n            if (h[j] < h[i]) {\n                if (dp[j] + 1 > dp[i]) { dp[i] = dp[j] + 1; cnt[i] = cnt[j]; }\n                else if (dp[j] + 1 == dp[i]) cnt[i] = (cnt[i] + cnt[j]) % MOD;\n            }\n        best = max(best, dp[i]);\n    }\n    long long total = 0;\n    for (int i = 0; i < n; ++i)\n        if (dp[i] == best) total = (total + cnt[i]) % MOD;\n    out << best << \"\\n\" << total << \"\\n\";\n}\n";
W["hsgi-cp-m11-balcony"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> h(n);\n    for (auto& x : h) in >> x;\n    const long long MOD = 1000000007;\n    vector<long long> dp(n, 1), cnt(n, 1);\n    long long best = 1;\n    for (int i = 0; i < n; ++i) {\n        for (int j = 0; j < i; ++j)\n            if (h[j] < h[i]) {\n                // near-miss: b\u1ecf nh\u00e1nh c\u1ed9ng khi B\u1eb0NG \u0111\u1ed9 d\u00e0i \u2014 cnt ch\u1ec9 ghi\n                // \u0111\u00e8, m\u1ea5t c\u00e1c c\u00e1ch song song (test 1 3 5 4 7 tr\u1ea3 1 thay 2)\n                if (dp[j] + 1 > dp[i]) { dp[i] = dp[j] + 1; cnt[i] = cnt[j]; }\n            }\n        best = max(best, dp[i]);\n    }\n    long long total = 0;\n    for (int i = 0; i < n; ++i)\n        if (dp[i] == best) total = (total + cnt[i]) % MOD;\n    out << best << \"\\n\" << total << \"\\n\";\n}\n";
R["hsgi-p12-knapsack"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, W; in >> n >> W;\n    vector<int> w(n), v(n);\n    for (int i = 0; i < n; ++i) in >> w[i] >> v[i];\n    vector<long long> dp(W + 1, 0);\n    for (int i = 0; i < n; ++i)\n        for (int j = W; j >= w[i]; --j)\n            dp[j] = max(dp[j], dp[j - w[i]] + v[i]);\n    out << dp[W] << \"\\n\";\n}\n";
W["hsgi-p12-knapsack"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, W; in >> n >> W;\n    vector<int> w(n), v(n);\n    for (int i = 0; i < n; ++i) in >> w[i] >> v[i];\n    // near-miss: THAM LAM theo t\u1ec9 l\u1ec7 gi\u00e1/tr\u1ecdng \u2014 ch\u1ec9 \u0111\u00fang v\u1edbi m\u00f3n \"chia\n    // \u0111\u01b0\u1ee3c\"; v\u00ed d\u1ee5 6/48 vs 5+5/70 ch\u1ecdn 6 v\u00e0 b\u1ecb k\u1eb9t 4 s\u1ee9c c\u00f2n l\u1ea1i\n    vector<pair<double,int>> order(n);\n    for (int i = 0; i < n; ++i)\n        order[i] = { (double)v[i] / w[i], i };\n    sort(order.rbegin(), order.rend());\n    long long val = 0; int cap = W;\n    for (auto& [r, i] : order)\n        if (w[i] <= cap) { val += v[i]; cap -= w[i]; }\n    out << val << \"\\n\";\n}\n";
R["hsgi-p12-coinmin"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int K, S; in >> K >> S;\n    vector<int> c(K);\n    for (auto& x : c) in >> x;\n    const int INF = 1e9;\n    vector<int> dp(S + 1, INF);\n    dp[0] = 0;\n    for (int k = 0; k < K; ++k)\n        for (int s = c[k]; s <= S; ++s)          // XU\u00d4I \u2014 v\u00f4 h\u1ea1n\n            if (dp[s - c[k]] + 1 < dp[s]) dp[s] = dp[s - c[k]] + 1;\n    out << (dp[S] >= INF ? -1 : dp[S]) << \"\\n\";\n}\n";
W["hsgi-p12-coinmin"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int K, S; in >> K >> S;\n    vector<int> c(K);\n    for (auto& x : c) in >> x;\n    sort(c.rbegin(), c.rend());\n    // near-miss: THAM LAM l\u1edbn-nh\u1ea5t-tr\u01b0\u1edbc \u2014 6,5,1 v\u00e0 S=7: 5+1+1 = 3 xu\n    // thay v\u00ec 6+1 = 2\n    int cnt = 0;\n    for (int k = 0; k < K; ++k) {\n        cnt += S / c[k];\n        S %= c[k];\n    }\n    out << (S > 0 ? -1 : cnt) << \"\\n\";\n}\n";
R["hsgi-p12-subsetcount"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, T; in >> n >> T;\n    vector<int> a(n);\n    for (auto& x : a) in >> x;\n    const long long MOD = 1000000007;\n    vector<long long> dp(T + 1, 0);\n    dp[0] = 1;\n    for (int i = 0; i < n; ++i)\n        for (int s = T; s >= a[i]; --s)          // NG\u01af\u1ee2C \u2014 0/1\n            dp[s] = (dp[s] + dp[s - a[i]]) % MOD;\n    out << dp[T] << \"\\n\";\n}\n";
W["hsgi-p12-subsetcount"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, T; in >> n >> T;\n    vector<int> a(n);\n    for (auto& x : a) in >> x;\n    const long long MOD = 1000000007;\n    vector<long long> dp(T + 1, 0);\n    dp[0] = 1;\n    // near-miss: v\u00f2ng XU\u00d4I \u2014 m\u1ed7i ph\u1ea7n t\u1eed d\u00f9ng l\u1ea1i \u0111\u01b0\u1ee3c; 1,1,2 v\u00e0 T=3\n    // \u0111\u1ebfm ph\u00ecnh c\u00e1c t\u1ed5 h\u1ee3p t\u00e1i s\u1eed d\u1ee5ng\n    for (int i = 0; i < n; ++i)\n        for (int s = a[i]; s <= T; ++s)\n            dp[s] = (dp[s] + dp[s - a[i]]) % MOD;\n    out << dp[T] << \"\\n\";\n}\n";
R["hsgi-p12-equal"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<int> a(n);\n    int S = 0;\n    for (auto& x : a) { in >> x; S += x; }\n    if (S % 2 != 0) { out << \"NO\" << \"\\n\"; return; }\n    int half = S / 2;\n    vector<char> dp(half + 1, 0);\n    dp[0] = 1;\n    for (int i = 0; i < n; ++i)\n        for (int s = half; s >= a[i]; --s)\n            if (dp[s - a[i]]) dp[s] = 1;\n    out << (dp[half] ? \"YES\" : \"NO\") << \"\\n\";\n}\n";
W["hsgi-p12-equal"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<int> a(n);\n    int S = 0;\n    for (auto& x : a) { in >> x; S += x; }\n    if (S % 2 != 0) { out << \"NO\" << \"\\n\"; return; }\n    int half = S / 2;\n    vector<char> dp(half + 1, 0);\n    dp[0] = 1;\n    // near-miss: v\u00f2ng XU\u00d4I \u2014 ph\u1ea7n t\u1eed d\u00f9ng l\u1ea1i; 1,2,5 n\u1eeda 4 \"\u0111\u1ea1t\" b\u1eb1ng\n    // 2+2 (m\u00f3n 2 d\u00f9ng hai l\u1ea7n) \u2192 YES sai\n    for (int i = 0; i < n; ++i)\n        for (int s = a[i]; s <= half; ++s)\n            if (dp[s - a[i]]) dp[s] = 1;\n    out << (dp[half] ? \"YES\" : \"NO\") << \"\\n\";\n}\n";
R["hsgi-p12-exact"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, W; in >> n >> W;\n    vector<int> w(n), v(n);\n    for (int i = 0; i < n; ++i) in >> w[i] >> v[i];\n    const long long NEG = -(1LL << 60);\n    vector<long long> dp(W + 1, NEG);\n    dp[0] = 0;\n    for (int i = 0; i < n; ++i)\n        for (int j = W; j >= w[i]; --j)\n            if (dp[j - w[i]] != NEG)\n                dp[j] = max(dp[j], dp[j - w[i]] + v[i]);\n    out << (dp[W] < 0 ? -1 : dp[W]) << \"\\n\";\n}\n";
W["hsgi-p12-exact"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, W; in >> n >> W;\n    vector<int> w(n), v(n);\n    for (int i = 0; i < n; ++i) in >> w[i] >> v[i];\n    // near-miss: balo TH\u01af\u1edcNG (n\u1ec1n 0, \u0111i\u1ec1u ki\u1ec7n \u2264) \u2014 kh\u00f4ng c\u1ea7n l\u1ea5p \u0111\u00fang;\n    // 4,5 + 7,9 v\u00e0 W=10 in 9 thay v\u00ec \u22121\n    vector<long long> dp(W + 1, 0);\n    for (int i = 0; i < n; ++i)\n        for (int j = W; j >= w[i]; --j)\n            dp[j] = max(dp[j], dp[j - w[i]] + v[i]);\n    out << dp[W] << \"\\n\";\n}\n";
R["hsgi-cp-m12-vault"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int K, S; in >> K >> S;\n    vector<int> c(K);\n    for (auto& x : c) in >> x;\n    const int INF = 1e9;\n    vector<int> dp(S + 1, INF);\n    dp[0] = 0;\n    for (int k = 0; k < K; ++k)\n        for (int s = c[k]; s <= S; ++s)\n            if (dp[s - c[k]] + 1 < dp[s]) dp[s] = dp[s - c[k]] + 1;\n    out << (dp[S] >= INF ? -1 : dp[S]) << \"\\n\";\n}\n";
W["hsgi-cp-m12-vault"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int K, S; in >> K >> S;\n    vector<int> c(K);\n    for (auto& x : c) in >> x;\n    sort(c.rbegin(), c.rend());\n    // near-miss: THAM LAM l\u1edbn-nh\u1ea5t-tr\u01b0\u1edbc \u2014 6,5,1 v\u00e0 S=7 ra 3 xu thay v\u00ec 2\n    int cnt = 0;\n    for (int k = 0; k < K; ++k) {\n        cnt += S / c[k];\n        S %= c[k];\n    }\n    out << (S > 0 ? -1 : cnt) << \"\\n\";\n}\n";
R["hsgi-p13-assign"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<vector<int>> c(n, vector<int>(n));\n    for (auto& r : c) for (auto& x : r) in >> x;\n    const int FULL = (1 << n) - 1;\n    vector<int> dp(1 << n, 1e9);\n    dp[0] = 0;\n    for (int m = 0; m < (1 << n); ++m) {\n        if (dp[m] >= 1e9) continue;\n        int i = __builtin_popcount(m);\n        if (i >= n) continue;\n        for (int j = 0; j < n; ++j)\n            if (!(m & (1 << j)))\n                dp[m | (1 << j)] = min(dp[m | (1 << j)], dp[m] + c[i][j]);\n    }\n    out << dp[FULL] << \"\\n\";\n}\n";
W["hsgi-p13-assign"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<vector<int>> c(n, vector<int>(n));\n    for (auto& r : c) for (auto& x : r) in >> x;\n    // near-miss: THAM LAM t\u1eebng h\u00e0ng ch\u1ecdn ca r\u1ebb nh\u1ea5t c\u00f2n tr\u1ed1ng \u2014 3\u00d73 v\u1edbi\n    // h\u00e0ng 0 r\u1ebb c\u01b0\u1edbp ca c\u1ee7a h\u00e0ng 1,2 \u2192 t\u1ed5ng l\u1edbn h\u01a1n t\u1ed1i \u01b0u\n    vector<char> used(n, 0);\n    long long tot = 0;\n    for (int i = 0; i < n; ++i) {\n        int bj = -1;\n        for (int j = 0; j < n; ++j)\n            if (!used[j] && (bj == -1 || c[i][j] < c[i][bj])) bj = j;\n        used[bj] = 1;\n        tot += c[i][bj];\n    }\n    out << tot << \"\\n\";\n}\n";
R["hsgi-p13-hampath"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<vector<char>> adj(n, vector<char>(n, 0));\n    for (int i = 0; i < m; ++i) {\n        int u, v; in >> u >> v; --u; --v;\n        adj[u][v] = adj[v][u] = 1;\n    }\n    const long long MOD = 1000000007;\n    vector<long long> dp(1 << n, 0);\n    dp[1] = 1;                       // b\u1eaft \u0111\u1ea7u \u1edf \u0111\u1ec9nh 0\n    long long total = 0;\n    // dp2[mask] = s\u1ed1 \u0111\u01b0\u1eddng k\u1ebft th\u00fac \u1edf \u0111\u1ec9nh ctz? c\u1ea7n last \u2014 d\u00f9ng m\u1ea3ng 2D\n    vector<vector<long long>> d2(1 << n, vector<long long>(n, 0));\n    d2[1][0] = 1;\n    for (int msk = 1; msk < (1 << n); ++msk)\n        for (int v = 0; v < n; ++v) {\n            if (!(msk & (1 << v)) || !d2[msk][v]) continue;\n            if (msk == (1 << n) - 1) {\n                total = (total + d2[msk][v]) % MOD;\n                continue;\n            }\n            for (int u = 0; u < n; ++u)\n                if (!(msk & (1 << u)) && adj[v][u])\n                    d2[msk | (1 << u)][u] = (d2[msk | (1 << u)][u] + d2[msk][v]) % MOD;\n        }\n    out << total << \"\\n\";\n}\n";
W["hsgi-p13-hampath"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<vector<char>> adj(n, vector<char>(n, 0));\n    for (int i = 0; i < m; ++i) {\n        int u, v; in >> u >> v; --u; --v;\n        adj[u][v] = adj[v][u] = 1;\n    }\n    // near-miss: QU\u00caN mask \u2014 ch\u1ec9 theo d\u00f5i \"\u0111ang \u0111\u1ee9ng \u0111\u00e2u\" v\u00e0 \u0111\u1ebfm \u0111\u01b0\u1eddng\n    // \u0111\u01a1n gi\u1ea3n b\u1eb1ng DFS kh\u00f4ng gi\u1edbi h\u1ea1n \u0111\u1ed9 d\u00e0i; \u0111\u1ebfm v\u01b0\u1ee3t (m\u1ecdi \u0111\u01b0\u1eddng \u0111\u01a1n,\n    // kh\u00f4ng ri\u00eang \u0111\u01b0\u1eddng qua \u0110\u1ee6 n \u0111\u1ec9nh) tr\u00ean \u0111\u1ed3 th\u1ecb nhi\u1ec1u c\u1ea1nh\n    vector<char> vis(n, 0);\n    // near-miss: \u0111\u1ebfm \u0111\u01b0\u1eddng Hamilton t\u1eeb M\u1eccI \u0111\u1ec9nh kh\u1edfi \u0111\u1ea7u (\u0111\u1ec1 c\u1ed1 \u0111\u1ecbnh\n    // \u0111\u1ec9nh 1) \u2014 \u0111\u1ebfm v\u01b0\u1ee3t: chu\u1ed7i 4 \u0111\u1ec9nh tr\u1ea3 2 thay v\u00ec 1\n    long long total = 0;\n    function<void(int)> dfs = [&](int u) {\n        vis[u] = 1;\n        bool all = true;\n        for (int v = 0; v < n; ++v) if (!vis[v]) all = false;\n        if (all) { total = (total + 1) % 1000000007; }\n        for (int v = 0; v < n; ++v)\n            if (adj[u][v] && !vis[v]) dfs(v);\n        vis[u] = 0;\n    };\n    for (int s = 0; s < n; ++s) dfs(s);\n    out << total << \"\\n\";\n}\n";
R["hsgi-p13-packing"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, W; in >> n >> W;\n    vector<int> w(n);\n    for (auto& x : w) in >> x;\n    const int INF = 1e9;\n    vector<pair<int,int>> dp(1 << n, {INF, 0});   // {s\u1ed1 h\u1ed9p, tr\u1ecdng d\u00f9ng c\u1ee7a h\u1ed9p hi\u1ec7n t\u1ea1i}\n    dp[0] = {0, W};                    // h\u1ed9p 0 \"\u0111\u00e3 \u0111\u1ea7y\" \u2014 g\u00f3i \u0111\u1ea7u m\u1edf h\u1ed9p m\u1edbi\n    for (int msk = 1; msk < (1 << n); ++msk) {\n        // th\u1eed M\u1eccI g\u00f3i p trong mask l\u00e0 \"g\u00f3i x\u1eed l\u00fd CU\u1ed0I\" \u2014 th\u1ee9 t\u1ef1 \u0111\u00f3ng h\u1ed9p\n        // kh\u00f4ng c\u1ed1 \u0111\u1ecbnh; ch\u1ed1t theo bit th\u1ea5p nh\u1ea5t s\u1ebd m\u1ea5t c\u00e1c h\u1ed9p ki\u1ec3u\n        // {A,C} xung quanh {B}\n        int rest = msk;\n        while (rest) {\n            int p = __builtin_ctz(rest);\n            rest &= rest - 1;\n            auto base = dp[msk ^ (1 << p)];\n            if (base.first >= INF) continue;\n            if (base.second + w[p] <= W)\n                dp[msk] = min(dp[msk], {base.first, base.second + w[p]});\n            dp[msk] = min(dp[msk], {base.first + 1, w[p]});\n        }\n    }\n    out << dp[(1 << n) - 1].first << \"\\n\";\n}\n";
W["hsgi-p13-packing"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, W; in >> n >> W;\n    vector<int> w(n);\n    for (auto& x : w) in >> x;\n    // near-miss: CH\u1ec8 coi t\u1ed5ng tr\u1ecdng l\u00e0 r\u00e0ng bu\u1ed9c \u2014 ceil(sum/W) h\u1ed9p;\n    // b\u1ecf qua vi\u1ec7c GH\u00c9P \u0110\u00d4I: 4,4,4 v\u1edbi W=6 t\u1ed5ng 12 \u2192 \"2 h\u1ed9p\" nh\u01b0ng hai\n    // g\u00f3i 4 kh\u00f4ng chung h\u1ed9p \u0111\u01b0\u1ee3c \u2192 \u0111\u00e1p \u00e1n 3\n    long long sum = 0;\n    for (int x : w) sum += x;\n    out << (sum + W - 1) / W << \"\\n\";\n}\n";
R["hsgi-p13-maxclique"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<int> adjm(n, 0);\n    for (int i = 0; i < m; ++i) {\n        int u, v; in >> u >> v; --u; --v;\n        adjm[u] |= 1 << v;\n        adjm[v] |= 1 << u;\n    }\n    // dp[mask] = 1 n\u1ebfu mask l\u00e0 clique; chuy\u1ec3n: clique + \u0111\u1ec9nh n\u1ed1i \u0111\u1ee7\n    vector<char> isClique(1 << n, 0);\n    int best = 0;\n    isClique[0] = 1;\n    for (int msk = 1; msk < (1 << n); ++msk) {\n        int low = __builtin_ctz(msk);           // \u0111\u1ec9nh m\u1edbi th\u00eam\n        int rest = msk ^ (1 << low);\n        if (isClique[rest] && (adjm[low] & rest) == rest)\n            isClique[msk] = 1;\n        if (isClique[msk]) best = max(best, __builtin_popcount(msk));\n    }\n    out << best << \"\\n\";\n}\n";
W["hsgi-p13-maxclique"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<int> adjm(n, 0);\n    for (int i = 0; i < m; ++i) {\n        int u, v; in >> u >> v; --u; --v;\n        adjm[u] |= 1 << v;\n        adjm[v] |= 1 << u;\n    }\n    // near-miss: THAM LAM theo b\u1eadc \u2014 ch\u1ecdn \u0111\u1ec9nh b\u1eadc cao nh\u1ea5t r\u1ed3i l\u1ecdc;\n    // \"hai tam gi\u00e1c gh\u00e9p qua c\u1ea7u\": b\u1eadc c\u1ee7a \u0111\u1ec9nh c\u1ea7u cao nh\u1ea5t b\u1ecb ch\u1ecdn\n    // tr\u01b0\u1edbc, nh\u00f3m ch\u1ed1t 2 thay v\u00ec 3\n    vector<int> deg(n);\n    for (int i = 0; i < n; ++i) deg[i] = __builtin_popcount(adjm[i]);\n    vector<int> order(n);\n    for (int i = 0; i < n; ++i) order[i] = i;\n    sort(order.begin(), order.end(), [&](int a, int b){ return deg[a] > deg[b]; });\n    vector<char> alive(n, 1);\n    int cnt = 0;\n    for (int v : order) {\n        if (!alive[v]) continue;\n        bool ok = true;\n        for (int u = 0; u < n; ++u)\n            if (alive[u] && u != v && !((adjm[v] >> u) & 1)) ok = false;\n        if (ok) { ++cnt; }\n        alive[v] = 0;\n        for (int u = 0; u < n; ++u)\n            if (!((adjm[v] >> u) & 1)) alive[u] = 0;\n    }\n    out << cnt << \"\\n\";\n}\n";
R["hsgi-p13-tsp"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<vector<int>> d(n, vector<int>(n));\n    for (auto& r : d) for (auto& x : r) in >> x;\n    if (n == 1) { out << 0 << \"\\n\"; return; }\n    const int INF = 1e9;\n    vector<vector<int>> dp(1 << n, vector<int>(n, INF));\n    dp[1][0] = 0;\n    for (int msk = 1; msk < (1 << n); ++msk)\n        for (int v = 0; v < n; ++v) {\n            if (!(msk & (1 << v)) || dp[msk][v] >= INF) continue;\n            for (int u = 0; u < n; ++u)\n                if (!(msk & (1 << u)))\n                    dp[msk | (1 << u)][u] = min(dp[msk | (1 << u)][u], dp[msk][v] + d[v][u]);\n        }\n    int best = INF;\n    for (int v = 0; v < n; ++v) best = min(best, dp[(1 << n) - 1][v]);\n    out << best << \"\\n\";\n}\n";
W["hsgi-p13-tsp"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<vector<int>> d(n, vector<int>(n));\n    for (auto& r : d) for (auto& x : r) in >> x;\n    // near-miss: NEAREST-NEIGHBOR t\u1eeb 0 \u2014 \u0111\u01b0\u1eddng ng\u1eafn hi\u1ec7n t\u1ea1i r\u1ed3i b\u01b0\u1edbc;\n    // kh\u00f4ng t\u1ed1i \u01b0u (TSP x\u1ea5p x\u1ec9 25% v\u1edbi metric), test \"b\u1eaby\" l\u1ed9\n    vector<char> vis(n, 0);\n    vis[0] = 1;\n    long long tot = 0;\n    int cur = 0;\n    for (int step = 1; step < n; ++step) {\n        int bj = -1;\n        for (int j = 0; j < n; ++j)\n            if (!vis[j] && (bj == -1 || d[cur][j] < d[cur][bj])) bj = j;\n        vis[bj] = 1;\n        tot += d[cur][bj];\n        cur = bj;\n    }\n    out << tot << \"\\n\";\n}\n";
R["hsgi-cp13-council"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<vector<int>> p(n, vector<int>(n));\n    for (auto& r : p) for (auto& x : r) in >> x;\n    const int FULL = (1 << n) - 1;\n    vector<int> dp(1 << n, -1);\n    dp[0] = 0;\n    for (int m = 0; m < (1 << n); ++m) {\n        if (dp[m] < 0) continue;\n        int i = __builtin_popcount(m);\n        if (i >= n) continue;\n        for (int j = 0; j < n; ++j)\n            if (!(m & (1 << j)))\n                dp[m | (1 << j)] = max(dp[m | (1 << j)], dp[m] + p[i][j]);\n    }\n    out << dp[FULL] << \"\\n\";\n}\n";
W["hsgi-cp13-council"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<vector<int>> p(n, vector<int>(n));\n    for (auto& r : p) for (auto& x : r) in >> x;\n    // near-miss: THAM LAM t\u1eebng h\u00e0ng ch\u1ecdn nhi\u1ec7m v\u1ee5 \u0111i\u1ec3m cao nh\u1ea5t c\u00f2n tr\u1ed1ng \u2014\n    // 9,8,1 / 9,1,1 / 1,1,1: h\u00e0ng 0 ch\u1ed1t 9, h\u00e0ng 1 ch\u1ed1t 1 (9 \u0111\u00e3 d\u00f9ng),\n    // h\u00e0ng 2 \u2192 1: 11; t\u1ed1i \u01b0u 8+9+1 = 18\n    vector<char> used(n, 0);\n    long long tot = 0;\n    for (int i = 0; i < n; ++i) {\n        int bj = -1;\n        for (int j = 0; j < n; ++j)\n            if (!used[j] && (bj == -1 || p[i][j] > p[i][bj])) bj = j;\n        used[bj] = 1;\n        tot += p[i][bj];\n    }\n    out << tot << \"\\n\";\n}\n";
R["hsgi-p14-sievecount"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int Q; in >> Q;\n    const int N = 10000000;\n    vector<char> comp(N + 1, 0);\n    vector<int> pi(N + 1, 0);\n    for (int i = 2; i <= N; ++i) {\n        if (!comp[i])\n            for (long long j = (long long)i * i; j <= N; j += i) comp[j] = 1;\n    }\n    for (int i = 2; i <= N; ++i) pi[i] = pi[i-1] + (comp[i] ? 0 : 1);\n    while (Q--) {\n        int x; in >> x;\n        out << pi[x] << \"\\n\";\n    }\n}\n";
W["hsgi-p14-sievecount"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int Q; in >> Q;\n    // near-miss: ki\u1ec3m nguy\u00ean t\u1ed1 CHIA TH\u1eec t\u1eebng truy v\u1ea5n \u2014 Q = 10^4 \u00d7\n    // N/ln N ph\u00e9p chia m\u1ed7i truy v\u1ea5n \u2192 qu\u00e1 h\u1ea1n t\u1ed5ng th\u1ec3\n    while (Q--) {\n        int x; in >> x;\n        int cnt = 0;\n        for (int p = 2; p <= x; ++p) {\n            bool ip = true;\n            for (int d = 2; d * d <= p; ++d)\n                if (p % d == 0) { ip = false; break; }\n            cnt += ip;\n        }\n        out << cnt << \"\\n\";\n    }\n}\n";
R["hsgi-p14-primecheck"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int Q; in >> Q;\n    while (Q--) {\n        long long x; in >> x;\n        bool ip = x >= 2;\n        for (long long d = 2; d * d <= x && ip; d += (d == 2 ? 1 : 2))\n            if (x % d == 0) ip = false;\n        out << (ip ? \"PRIME\" : \"COMPOSITE\") << \"\\n\";\n    }\n}\n";
W["hsgi-p14-primecheck"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int Q; in >> Q;\n    while (Q--) {\n        long long x; in >> x;\n        // near-miss: d * d l\u00e0 NH\u00c2N INT \u2014 d*d tr\u00e0n khi d > ~46341, v\u00f2ng\n        // d\u1eebng s\u1edbm; h\u1ee3p s\u1ed1 c\u00f3 \u01b0\u1edbc nh\u1ecf nh\u1ea5t > 46341 (vd 104729\u00b2) b\u1ecb\n        // g\u1ecdi nh\u1ea7m PRIME\n        int d = 2;\n        bool ip = x >= 2;\n        while (d * d <= x) {\n            if (x % d == 0) { ip = false; break; }\n            ++d;\n        }\n        out << (ip ? \"PRIME\" : \"COMPOSITE\") << \"\\n\";\n    }\n}\n";
R["hsgi-p14-lcmrange"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long L, R; in >> L >> R;\n    const long long MOD = 1000000007;\n    const int N = 1000000;\n    vector<char> comp(N + 1, 0);\n    for (int i = 2; i <= N; ++i)\n        if (!comp[i])\n            for (long long j = (long long)i * i; j <= N; j += i) comp[j] = 1;\n    long long ans = 1;\n    for (long long p = 2; p <= R; ++p) {\n        if (comp[p]) continue;\n        // lu\u1ef9 th\u1eeba p^e L\u1edaN NH\u1ea4T c\u00f3 b\u1ed9i trong [L, R]:\n        // b\u1ed9i c\u1ee7a pw trong \u0111o\u1ea1n t\u1ed3n t\u1ea1i \u21d4 floor(R/pw) \u2265 ceil(L/pw)\n        long long best = 1, pw = 1;\n        while (pw * p <= R) {\n            pw *= p;\n            if (R / pw >= (L + pw - 1) / pw) best = pw;\n        }\n        if (best > 1) ans = ans % MOD * (best % MOD) % MOD;\n    }\n    out << ans << \"\\n\";\n}\n";
W["hsgi-p14-lcmrange"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long L, R; in >> L >> R;\n    const long long MOD = 1000000007;\n    // near-miss: NH\u00c2N T\u1eeaNG S\u1ed0 trong \u0111o\u1ea1n v\u1edbi mod \u2014 lcm KH\u00d4NG ph\u1ea3i t\u00edch\n    // mod: 8,9,10 \u2192 t\u00edch mod = 720/2? \u2014 k\u1ebft qu\u1ea3 sai m\u1ecdi \u0111o\u1ea1n d\u00e0i\n    long long ans = 1;\n    for (long long x = L; x <= R; ++x)\n        ans = ans % MOD * (x % MOD) % MOD;\n    out << ans << \"\\n\";\n}\n";
R["hsgi-p14-divisors"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int Q; in >> Q;\n    while (Q--) {\n        long long n; in >> n;\n        long long total = 1;\n        for (long long d = 2; d * d <= n; ++d) {\n            if (n % d == 0) {\n                int k = 0;\n                while (n % d == 0) { n /= d; ++k; }\n                total *= (k + 1);\n            }\n        }\n        if (n > 1) total *= 2;\n        out << total << \"\\n\";\n    }\n}\n";
W["hsgi-p14-divisors"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int Q; in >> Q;\n    while (Q--) {\n        long long n; in >> n;\n        // near-miss: LI\u1ec6T K\u00ca \u01b0\u1edbc t\u1edbi sqrt r\u1ed3i \u00d72 \u2014 s\u1ed1 CH\u00cdNH PH\u01af\u01a0NG b\u1ecb\n        // \u0111\u1ebfm th\u1eeba 1 (\u01b0\u1edbc c\u0103n \u0111\u01b0\u1ee3c t\u00ednh hai l\u1ea7n)\n        long long cnt = 0;\n        for (long long d = 1; d * d <= n; ++d)\n            if (n % d == 0) cnt += 2;\n        out << cnt << \"\\n\";\n    }\n}\n";
R["hsgi-p14-modpowsum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int Q; in >> Q;\n    while (Q--) {\n        long long a, b, m; in >> a >> b >> m;\n        long long r = 1 % m;\n        a %= m;\n        while (b > 0) {\n            if (b & 1) r = r * a % m;\n            a = a * a % m;\n            b >>= 1;\n        }\n        out << r << \"\\n\";\n    }\n}\n";
W["hsgi-p14-modpowsum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int Q; in >> Q;\n    while (Q--) {\n        long long a, b, m; in >> a >> b >> m;\n        // near-miss: nh\u00e2n d\u1ea7n O(b) \u2014 b t\u1edbi 10^18 \u2192 qu\u00e1 h\u1ea1n t\u1ee9c th\u00ec\n        long long r = 1 % m;\n        for (long long i = 0; i < b; ++i) r = r * (a % m) % m;\n        out << r << \"\\n\";\n    }\n}\n";
R["hsgi-cp-m14-fence"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int Q; in >> Q;\n    const int N = 10000000;\n    vector<char> comp(N + 1, 0);\n    vector<int> pi(N + 1, 0);\n    for (int i = 2; i <= N; ++i)\n        if (!comp[i])\n            for (long long j = (long long)i * i; j <= N; j += i) comp[j] = 1;\n    for (int i = 2; i <= N; ++i) pi[i] = pi[i-1] + (comp[i] ? 0 : 1);\n    while (Q--) {\n        int L, R; in >> L >> R;\n        out << pi[R] - pi[L - 1] << \"\\n\";\n    }\n}\n";
W["hsgi-cp-m14-fence"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int Q; in >> Q;\n    // near-miss: ki\u1ec3m t\u1eebng s\u1ed1 trong \u0111o\u1ea1n b\u1eb1ng chia th\u1eed \u2014 m\u1ed7i truy v\u1ea5n\n    // (R \u2212 L)\u00b7sqrt(R) ph\u00e9p; Q = 10^4 truy v\u1ea5n to\u00e0n d\u1ea3i \u2192 qu\u00e1 h\u1ea1n\n    while (Q--) {\n        int L, R; in >> L >> R;\n        int cnt = 0;\n        for (int x = L; x <= R; ++x) {\n            bool ip = x >= 2;\n            for (long long d = 2; d * d <= x && ip; ++d)\n                if (x % d == 0) ip = false;\n            cnt += ip;\n        }\n        out << cnt << \"\\n\";\n    }\n}\n";
R["hsgi-p15-paliprefix"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; in >> s;\n    int n = s.size();\n    // KMP trick: s + '#' + reverse(s); pi t\u1ea1i v\u1ecb tr\u00ed cu\u1ed1i = bi\u00ean d\u00e0i nh\u1ea5t\n    // c\u1ee7a reverse(s) kh\u1edbp h\u1eadu t\u1ed1... chu\u1ea9n h\u01a1n: ti\u1ec1n t\u1ed1 \u0111\u1ed1i x\u1ee9ng d\u00e0i nh\u1ea5t\n    // = bi\u00ean d\u00e0i nh\u1ea5t p c\u1ee7a s sao cho p == reverse(p) \u2014 pi[n-1] c\u1ee7a\n    // t = s + '#' + reverse(s) ch\u00ednh l\u00e0 \u0111\u1ed9 d\u00e0i \u0111\u00f3\n    string r(s.rbegin(), s.rend());\n    string t = s + \"#\" + r;\n    int m = t.size();\n    vector<int> pi(m, 0);\n    for (int i = 1; i < m; ++i) {\n        int j = pi[i-1];\n        while (j > 0 && t[i] != t[j]) j = pi[j-1];\n        if (t[i] == t[j]) ++j;\n        pi[i] = j;\n    }\n    out << pi[m-1] << \"\\n\";\n}\n";
W["hsgi-p15-paliprefix"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; in >> s;\n    int n = s.size();\n    // near-miss: so TR\u1ef0C TI\u1ebeP t\u1eebng \u0111\u1ed9 d\u00e0i ti\u1ec1n t\u1ed1 v\u1edbi \u0111\u1ea3o \u2014 O(n\u00b2) k\u00fd t\u1ef1;\n    // n = 10^6 to\u00e0n 'a' \u2192 10^12 ph\u00e9p so \u2192 qu\u00e1 h\u1ea1n ch\u1eafc ch\u1eafn\n    int best = 0;\n    for (int k = 1; k <= n; ++k) {\n        bool ok = true;\n        for (int i = 0; i < k; ++i)\n            if (s[i] != s[k-1-i]) { ok = false; break; }\n        if (ok) best = k;\n    }\n    out << best << \"\\n\";\n}\n";
R["hsgi-p15-subcount"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; in >> s;\n    int n = s.size();\n    const long long MOD1 = 1000000007, MOD2 = 998244353, B = 131;\n    vector<long long> H1(n + 1, 0), P1(n + 1, 1), H2(n + 1, 0), P2(n + 1, 1);\n    for (int i = 0; i < n; ++i) {\n        H1[i+1] = (H1[i] * B + s[i]) % MOD1;\n        P1[i+1] = P1[i] * B % MOD1;\n        H2[i+1] = (H2[i] * B + s[i]) % MOD2;\n        P2[i+1] = P2[i] * B % MOD2;\n    }\n    long long total = 0;\n    vector<pair<long long,long long>> hs;\n    for (int L = 1; L <= n; ++L) {\n        hs.clear();\n        for (int l = 0; l + L <= n; ++l) {\n            int r = l + L;\n            long long h1 = (H1[r] - H1[l] * P1[L]) % MOD1;\n            if (h1 < 0) h1 += MOD1;\n            long long h2 = (H2[r] - H2[l] * P2[L]) % MOD2;\n            if (h2 < 0) h2 += MOD2;\n            hs.push_back({h1, h2});\n        }\n        sort(hs.begin(), hs.end());\n        total += unique(hs.begin(), hs.end()) - hs.begin();\n    }\n    out << total << \"\\n\";\n}\n";
W["hsgi-p15-subcount"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; in >> s;\n    int n = s.size();\n    // near-miss: \u0111\u1ebfm M\u1eccI c\u1eb7p v\u1ecb tr\u00ed (l, r) \u2014 \u0111\u1ebfm L\u1ea6N XU\u1ea4T HI\u1ec6N ch\u1ee9 kh\u00f4ng\n    // ph\u1ea3i x\u00e2u PH\u00c2N BI\u1ec6T; 'aba' tr\u1ea3 6 thay v\u00ec 5, 'aaaa' tr\u1ea3 10 thay v\u00ec 4\n    out << (long long)n * (n + 1) / 2 << \"\\n\";\n}\n";
R["hsgi-p15-occurrences"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string p, t; in >> p >> t;\n    string s = p + \"#\" + t;\n    int m = p.size(), M = s.size();\n    vector<int> pi(M, 0);\n    for (int i = 1; i < M; ++i) {\n        int j = pi[i-1];\n        while (j > 0 && s[i] != s[j]) j = pi[j-1];\n        if (s[i] == s[j]) ++j;\n        pi[i] = j;\n    }\n    long long cnt = 0;\n    for (int i = m + 1; i < M; ++i)\n        if (pi[i] == m) ++cnt;\n    out << cnt << \"\\n\";\n}\n";
W["hsgi-p15-occurrences"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string p, t; in >> p >> t;\n    int m = p.size(), n = t.size();\n    // near-miss: qu\u00e9t t\u1eebng v\u1ecb tr\u00ed, so l\u1ea1i T\u1eea \u0110\u1ea6U m\u1eabu \u2014 O(n\u00b7m); m\u1eabu t\u1ef1\n    // l\u1eb7p (aab trong aab\u00d7N) bi\u1ebfn th\u00e0nh (n\u00b7m) \u2248 10^12 ph\u00e9p \u2192 qu\u00e1 h\u1ea1n\n    long long cnt = 0;\n    for (int i = 0; i + m <= n; ++i) {\n        bool ok = true;\n        for (int j = 0; j < m; ++j)\n            if (t[i + j] != p[j]) { ok = false; break; }\n        cnt += ok;\n    }\n    out << cnt << \"\\n\";\n}\n";
R["hsgi-p15-period"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; in >> s;\n    int n = s.size();\n    vector<int> pi(n, 0);\n    for (int i = 1; i < n; ++i) {\n        int j = pi[i-1];\n        while (j > 0 && s[i] != s[j]) j = pi[j-1];\n        if (s[i] == s[j]) ++j;\n        pi[i] = j;\n    }\n    int cand = n - pi[n-1];\n    if (cand < n && n % cand == 0) out << cand << \"\\n\";\n    else out << -1 << \"\\n\";\n}\n";
W["hsgi-p15-period"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; in >> s;\n    int n = s.size();\n    // near-miss: th\u1eed M\u1eccI \u01b0\u1edbc d c\u1ee7a n v\u00e0 so s\u00e1nh kh\u1ed1i \u2014 \u0111\u00fang k\u1ebft qu\u1ea3 nh\u01b0ng\n    // O(n\u00b7s\u1ed1 \u01b0\u1edbc) \u2248 O(n^1.1)? th\u1ef1c t\u1ebf: m\u1ed7i \u01b0\u1edbc ki\u1ec3m O(n) \u2192 t\u1ed5ng O(n\u00b7d(n))\n    // v\u1eabn nhanh v\u1edbi n = 10^6 (d \u2264 240)... l\u1ed7i th\u1eadt: ki\u1ec3m d t\u1eeb n/2 XU\u1ed0NG\n    // nh\u01b0ng QU\u00caN ki\u1ec3m n % d == 0 tr\u01b0\u1edbc \u2014 so kh\u1ed1i l\u1ec7ch \u2192 k\u1ebft qu\u1ea3 sai\n    for (int d = n / 2; d >= 1; --d) {\n        bool ok = true;\n        for (int i = 0; i < n; ++i)\n            if (s[i] != s[i % d]) { ok = false; break; }\n        if (ok) { out << d << \"\\n\"; return; }\n    }\n    out << -1 << \"\\n\";\n}\n";
R["hsgi-p15-hasheq"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; in >> s;\n    int n = s.size();\n    const long long MOD1 = 1000000007, MOD2 = 998244353, B = 131;\n    vector<long long> H1(n + 1, 0), P1(n + 1, 1), H2(n + 1, 0), P2(n + 1, 1);\n    for (int i = 0; i < n; ++i) {\n        H1[i+1] = (H1[i] * B + s[i]) % MOD1;\n        P1[i+1] = P1[i] * B % MOD1;\n        H2[i+1] = (H2[i] * B + s[i]) % MOD2;\n        P2[i+1] = P2[i] * B % MOD2;\n    }\n    auto get = [&](vector<long long>& H, vector<long long>& P, long long MOD, int l, int r) {\n        long long h = (H[r] - H[l] * P[r - l]) % MOD;\n        if (h < 0) h += MOD;\n        return h;\n    };\n    int Q; in >> Q;\n    while (Q--) {\n        int l1, r1, l2, r2; in >> l1 >> r1 >> l2 >> r2;\n        bool eq = (r1 - l1) == (r2 - l2)\n            && get(H1, P1, MOD1, l1 - 1, r1) == get(H1, P1, MOD1, l2 - 1, r2)\n            && get(H2, P2, MOD2, l1 - 1, r1) == get(H2, P2, MOD2, l2 - 1, r2);\n        out << (eq ? \"YES\" : \"NO\") << \"\\n\";\n    }\n}\n";
W["hsgi-p15-hasheq"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; in >> s;\n    int n = s.size();\n    // near-miss: SO TR\u1ef0C TI\u1ebeP t\u1eebng truy v\u1ea5n \u2014 O(Q\u00b7n); Q = 2\u00b710^5 \u00d7 \u0111o\u1ea1n\n    // 10^5 k\u00fd t\u1ef1 = 2\u00b710^10 ph\u00e9p \u2192 qu\u00e1 h\u1ea1n ch\u1eafc ch\u1eafn\n    int Q; in >> Q;\n    while (Q--) {\n        int l1, r1, l2, r2; in >> l1 >> r1 >> l2 >> r2;\n        bool eq = (r1 - l1) == (r2 - l2);\n        for (int i = 0; eq && i < r1 - l1 + 1; ++i)\n            if (s[l1 - 1 + i] != s[l2 - 1 + i]) eq = false;\n        out << (eq ? \"YES\" : \"NO\") << \"\\n\";\n    }\n}\n";
R["hsgi-cp-m15-mirror"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; in >> s;\n    int n = s.size();\n    const long long MOD1 = 1000000007, MOD2 = 998244353, B = 131;\n    string r(s.rbegin(), s.rend());\n    // hash c\u1ee7a s v\u00e0 c\u1ee7a reverse(s); \u0111o\u1ea1n [l..r] (1-based) \u0111\u1ed1i x\u1ee9ng \u21d4\n    // hash_s(l..r) == hash_r(n+1-r .. n+1-l)\n    auto build = [&](const string& x) {\n        vector<long long> H(n + 1, 0), P(n + 1, 1);\n        for (int i = 0; i < n; ++i) {\n            H[i+1] = (H[i] * B + x[i]) % MOD1;\n            P[i+1] = P[i] * B % MOD1;\n        }\n        return make_pair(H, P);\n    };\n    auto [Hs, Ps] = build(s);\n    auto [Hr, Pr] = build(r);\n    auto get = [&](vector<long long>& H, vector<long long>& P, int l, int rr) {\n        long long h = (H[rr] - H[l] * P[rr - l]) % MOD1;\n        if (h < 0) h += MOD1;\n        return h;\n    };\n    int Q; in >> Q;\n    while (Q--) {\n        int l, rr; in >> l >> rr;\n        bool eq = get(Hs, Ps, l - 1, rr) == get(Hr, Pr, n - rr, n - l + 1);\n        out << (eq ? \"YES\" : \"NO\") << \"\\n\";\n    }\n}\n";
W["hsgi-cp-m15-mirror"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; in >> s;\n    int n = s.size();\n    // near-miss: SO K\u00dd T\u1ef0 t\u1eebng truy v\u1ea5n \u2014 O(Q\u00b7n); Q = 2\u00b710^5 \u00d7 n = 2\u00b710^5\n    // \u2192 4\u00b710^10 ph\u00e9p \u2192 qu\u00e1 h\u1ea1n ch\u1eafc ch\u1eafn\n    int Q; in >> Q;\n    while (Q--) {\n        int l, rr; in >> l >> rr;\n        bool eq = true;\n        for (int i = l - 1, j = rr - 1; i < j; ++i, --j)\n            if (s[i] != s[j]) { eq = false; break; }\n        out << (eq ? \"YES\" : \"NO\") << \"\\n\";\n    }\n}\n";
R["hsgi-p16-window"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <map>\n#include <unordered_map>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; long long k; in >> s >> k;\n    int n = s.size();\n    vector<int> cnt(26, 0);\n    int d = 0, j = 0, best = 0;\n    for (int i = 0; i < n; ++i) {\n        if (cnt[s[i] - 'a']++ == 0) ++d;\n        while (d > k) {\n            if (--cnt[s[j] - 'a'] == 0) --d;\n            ++j;\n        }\n        best = max(best, i - j + 1);\n    }\n    out << best << \"\\n\";\n}\n";
W["hsgi-p16-window"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <map>\n#include <unordered_map>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; long long k; in >> s >> k;\n    int n = s.size();\n    // near-miss: QU\u00c9T M\u1eccI C\u1eb6P (l, r) \u2014 O(n^2); n = 10^6 \u2192 qu\u00e1 h\u1ea1n ch\u1eafc\n    vector<int> cnt(26, 0);\n    int best = 0;\n    for (int l = 0; l < n; ++l) {\n        for (int x = 0; x < 26; ++x) cnt[x] = 0;\n        int d = 0;\n        for (int r = l; r < n; ++r) {\n            if (cnt[s[r] - 'a']++ == 0) ++d;\n            if (d > k) break;\n            best = max(best, r - l + 1);\n        }\n    }\n    out << best << \"\\n\";\n}\n";
R["hsgi-p16-negsum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <map>\n#include <unordered_map>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long K; in >> n >> K;\n    unordered_map<long long, long long> m;\n    m[0] = 1;\n    long long s = 0, c = 0;\n    for (int i = 0; i < n; ++i) {\n        long long x; in >> x;\n        s += x;\n        auto it = m.find(s - K);\n        if (it != m.end()) c += it->second;\n        ++m[s];\n    }\n    out << c << \"\\n\";\n}\n";
W["hsgi-p16-negsum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <map>\n#include <unordered_map>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long K; in >> n >> K;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    // near-miss: C\u1eecA S\u1ed4 TR\u01af\u1ee2T \u2014 sai v\u1edbi s\u1ed1 \u00e2m (t\u1ed5ng kh\u00f4ng \u0111\u01a1n \u0111i\u1ec7u):\n    // m\u1ed7i l m\u1edf r\u1ed9ng r \u0111\u1ebfn khi t\u1ed5ng v\u01b0\u1ee3t K r\u1ed3i d\u1eebng; b\u1ecf s\u00f3t/miscount\n    // m\u1ecdi \u0111o\u1ea1n c\u00f3 t\u1ed5ng v\u01b0\u1ee3t r\u1ed3i quay l\u1ea1i\n    long long c = 0;\n    for (int l = 0; l < n; ++l) {\n        long long s = 0;\n        for (int r = l; r < n && s <= K; ++r) {\n            s += a[r];\n            if (s == K) ++c;\n        }\n    }\n    out << c << \"\\n\";\n}\n";
R["hsgi-p16-pairs"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <map>\n#include <unordered_map>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long S; in >> n >> S;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    sort(a.begin(), a.end());\n    long long c = 0;\n    int i = 0, j = n - 1;\n    // hai con tr\u1ecf tr\u00ean m\u1ea3ng \u0111\u00e3 sort; nh\u00f3m b\u1eb1ng nhau x\u1eed l\u00fd \u0111\u1ebfm ch\u00e9o\n    while (i < j) {\n        long long s = a[i] + a[j];\n        if (s < S) ++i;\n        else if (s > S) --j;\n        else if (a[i] == a[j]) {\n            long long m = j - i + 1;\n            c += m * (m - 1) / 2;\n            break;\n        } else {\n            long long ci = 1, cj = 1;\n            while (i + 1 < j && a[i + 1] == a[i]) { ++i; ++ci; }\n            while (j - 1 > i && a[j - 1] == a[j]) { --j; ++cj; }\n            c += ci * cj;\n            ++i; --j;\n        }\n    }\n    out << c << \"\\n\";\n}\n";
W["hsgi-p16-pairs"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <map>\n#include <unordered_map>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long S; in >> n >> S;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    // near-miss: HAI V\u00d2NG \u0111\u1ebfm t\u1eebng c\u1eb7p \u2014 O(n^2); n = 2\u00b710^5 \u2192 qu\u00e1 h\u1ea1n\n    long long c = 0;\n    for (int i = 0; i < n; ++i)\n        for (int j = i + 1; j < n; ++j)\n            if (a[i] + a[j] == S) ++c;\n    out << c << \"\\n\";\n}\n";
R["hsgi-p16-maxsub"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <map>\n#include <unordered_map>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        long long x; in >> x;\n        cur = max(cur + x, x);\n        best = max(best, cur);\n    }\n    out << best << \"\\n\";\n}\n";
W["hsgi-p16-maxsub"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <map>\n#include <unordered_map>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    // near-miss: init best = 0 \u2014 m\u1ea3ng TO\u00c0N \u00c2M tr\u1ea3 0 thay v\u00ec ph\u1ea7n t\u1eed\n    // \u00e2m l\u1edbn nh\u1ea5t (\u0111o\u1ea1n kh\u00e1c r\u1ed7ng l\u00e0 b\u1eaft bu\u1ed9c)\n    long long best = 0, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        long long x; in >> x;\n        cur = max(cur + x, x);\n        best = max(best, cur);\n    }\n    out << best << \"\\n\";\n}\n";
