W["hsgi-p16-jobs"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <map>\n#include <unordered_map>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long a, b; in >> a >> b;\n    // near-miss: lu\u00f4n gi\u1eef vi\u1ec7c cu\u1ed1i \u1edf m\u00e1y A (kh\u00f4ng x\u00e9t l\u1ef1a ch\u1ecdn\n    // chuy\u1ec3n) \u2014 b\u1ecf nh\u1ecbp th\u1eafng khi b < a\n    out << max(a, b) << \"\\n\";\n}\n";
R["hsgi-cp-m16-josephus"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <map>\n#include <unordered_map>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long k; in >> n >> k;\n    vector<int> a(n + 1);\n    for (int i = 1; i <= n; ++i) in >> a[i];\n    // Fenwick tr\u00ean V\u1eca TR\u00cd: t\u1ed3n t\u1ea1i = 1\n    vector<int> fen(n + 1, 0);\n    auto upd = [&](int i, int d) { for (; i <= n; i += i & (-i)) fen[i] += d; };\n    auto kth = [&](long long j) {          // ng\u01b0\u1eddi c\u00f2n l\u1ea1i th\u1ee9 j\n        int pos = 0;\n        long long r = j;\n        for (int pw = (1 << 17); pw > 0; pw >>= 1) {\n            if (pos + pw <= n && fen[pos + pw] < r) {\n                pos += pw;\n                r -= fen[pos];\n            }\n        }\n        return pos + 1;\n    };\n    for (int i = 1; i <= n; ++i) upd(i, 1);\n    long long start = 1;                   // th\u1ee9 h\u1ea1ng b\u1eaft \u0111\u1ea7u l\u01b0\u1ee3t (1-based)\n    int rem = n;\n    while (rem > 1) {\n        long long j = ((start - 1 + k - 1) % rem) + 1;\n        int p = kth(j);\n        upd(p, -1);\n        --rem;\n        start = j;                          // k\u1ebf ti\u1ebfp chi\u1ebfm ch\u1ed7 th\u1ee9 j\n    }\n    out << a[kth(1)] << \"\\n\";\n}\n";
W["hsgi-cp-m16-josephus"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <map>\n#include <unordered_map>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long k; in >> n >> k;\n    vector<int> a(n + 1);\n    for (int i = 1; i <= n; ++i) in >> a[i];\n    // near-miss: h\u00e0ng \u0111\u1ee3i qu\u00e9t v\u00f2ng \u0110\u00daNG C\u01a0 CH\u1ebe \u0111\u1ebfm nh\u01b0ng d\u1eebng khi h\u00e0ng\n    // \u0111\u1ee3i c\u00f2n M\u1ed8T PH\u1ea6N T\u1eec \u2014 in ph\u1ea7n t\u1eed S\u1ed0NG S\u00d3T thay v\u00ec ng\u01b0\u1eddi b\u1ecb LO\u1ea0I\n    // CU\u1ed0I (\u0111\u1ec1 y\u00eau c\u1ea7u gi\u00e1 tr\u1ecb ng\u01b0\u1eddi b\u1ecb lo\u1ea1i cu\u1ed1i); g\u00e3y h\u00e0nh vi tr\u00ean\n    // m\u1ecdi test\n    deque<int> q;\n    for (int i = 1; i <= n; ++i) q.push_back(i);\n    while ((int)q.size() > 1) {\n        long long steps = k % q.size();\n        for (long long s = 0; s < steps; ++s) { q.push_back(q.front()); q.pop_front(); }\n        q.pop_front();\n    }\n    out << a[q.front()] << \"\\n\";\n}\n";
R["hsgi-p17-binoff"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    long long x; in >> x;\n    int lo = 0, hi = n - 1, ans = -1;\n    while (lo <= hi) {\n        int mid = lo + (hi - lo) / 2;\n        if (a[mid] == x) { ans = mid; break; }\n        else if (a[mid] < x) lo = mid + 1;\n        else hi = mid - 1;\n    }\n    out << ans << \"\\n\";\n}\n";
