R["hsgi-p18-paren"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; in >> s;\n    int n = s.size();\n    // stack ch\u1ec9 s\u1ed1; ph\u1ea7n t\u1eed \u0111\u00e1y l\u00e0 \"h\u00e0ng r\u00e0o\" (ch\u1ec9 s\u1ed1 tr\u01b0\u1edbc d\u00e3y h\u1ee3p l\u1ec7)\n    vector<int> st;\n    st.reserve(n + 1);\n    st.push_back(-1);\n    int best = 0;\n    for (int i = 0; i < n; ++i) {\n        if (s[i] == '(') st.push_back(i);\n        else {\n            st.pop_back();\n            if (st.empty()) st.push_back(i);\n            else best = max(best, i - st.back());\n        }\n    }\n    out << best << \"\\n\";\n}\n";
W["hsgi-p18-paren"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; in >> s;\n    // near-miss: \u0111\u1ebfm S\u1ed0 C\u1eb6P kh\u1edbp \u1edf b\u1ea5t k\u1ef3 \u0111\u00e2u \u2014 b\u1ecf \u0111i\u1ec1u ki\u1ec7n LI\u00caN TI\u1ebeP\n    int d = 0, c = 0;\n    for (char ch : s) {\n        if (ch == '(') ++d;\n        else if (d > 0) { --d; c += 2; }\n    }\n    out << c << \"\\n\";\n}\n";
R["hsgi-p18-winmax"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, k; in >> n >> k;\n    vector<int> a(n);\n    for (auto& x : a) in >> x;\n    // deque \u0111\u01a1n \u0111i\u1ec7u GI\u1ea2M ch\u1ec9 s\u1ed1; \u0111\u1ea7u deque = max c\u1eeda s\u1ed5 hi\u1ec7n h\u00e0nh\n    deque<int> dq;\n    bool first = true;\n    for (int i = 0; i < n; ++i) {\n        while (!dq.empty() && a[dq.back()] <= a[i]) dq.pop_back();\n        dq.push_back(i);\n        if (dq.front() <= i - k) dq.pop_front();\n        if (i >= k - 1) {\n            if (!first) out << \" \";\n            out << a[dq.front()];\n            first = false;\n        }\n    }\n    out << \"\\n\";\n}\n";
W["hsgi-p18-winmax"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, k; in >> n >> k;\n    vector<int> a(n);\n    for (auto& x : a) in >> x;\n    // near-miss: QU\u00caN pop ch\u1ec9 s\u1ed1 h\u1ebft h\u1ea1n \u1edf \u0111\u1ea7u deque \u2014 max c\u0169 \"k\u1eb9t\"\n    // trong deque v\u00e0 \u0111\u01b0\u1ee3c b\u00e1o sai sau khi r\u1eddi c\u1eeda s\u1ed5\n    deque<int> dq;\n    bool first = true;\n    for (int i = 0; i < n; ++i) {\n        while (!dq.empty() && a[dq.back()] <= a[i]) dq.pop_back();\n        dq.push_back(i);\n        if (i >= k - 1) {\n            if (!first) out << \" \";\n            out << a[dq.front()];\n            first = false;\n        }\n    }\n    out << \"\\n\";\n}\n";
