R["hsgi-cp18-stair"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> c(n);\n    for (auto& x : c) in >> x;\n    // dp0 = chi ph\u00ed \u0111\u1ee9ng tr\u00ean b\u1eadc i\u22122, dp1 = b\u1eadc i\u22121; s\u00e0n = 0\n    long long dp0 = 0, dp1 = 0;\n    for (int i = 0; i < n; ++i) {\n        long long nd = min(dp0, dp1) + c[i];\n        dp0 = dp1;\n        dp1 = nd;\n    }\n    out << min(dp0, dp1) << \"\\n\";\n}\n";
W["hsgi-cp18-stair"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> c(n);\n    for (auto& x : c) in >> x;\n    // near-miss: tham lam \u2014 t\u1ea1i m\u1ed7i v\u1ecb tr\u00ed b\u01b0\u1edbc l\u00ean b\u1eadc \"r\u1ebb h\u01a1n\" k\u1ebf\n    // ti\u1ebfp; quy\u1ebft \u0111\u1ecbnh c\u1ee5c b\u1ed9 b\u1ecf qua ph\u00ed c\u00e1c b\u1eadc sau\n    long long total = 0;\n    int i = -1;\n    while (i < n - 1) {\n        long long one = (i + 1 < n) ? c[i + 1] : 0;\n        long long two = (i + 2 < n) ? c[i + 2] : 0;\n        if (i + 2 < n && two <= one) i += 2;\n        else i += 1;\n        total += c[i];\n    }\n    out << total << \"\\n\";\n}\n";
R["hsgi-cp18-town"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<int> p(n + 1);\n    for (int i = 1; i <= n; ++i) p[i] = i;\n    auto find = [&](int x) {\n        while (p[x] != x) { p[x] = p[p[x]]; x = p[x]; }\n        return x;\n    };\n    for (int i = 0; i < m; ++i) {\n        int a, b; in >> a >> b;\n        p[find(a)] = find(b);\n    }\n    int comps = 0;\n    for (int i = 1; i <= n; ++i)\n        if (find(i) == i) ++comps;\n    out << comps << \"\\n\";\n}\n";
W["hsgi-cp18-town"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<int> p(n + 1);\n    for (int i = 1; i <= n; ++i) p[i] = i;\n    // near-miss: g\u00e1n cha TR\u1ef0C TI\u1ebeP p[b] = a r\u1ed3i \u0111\u1ebfm s\u1ed1 t\u00f2a B\u1eca G\u00c1N CHA\n    // (p[i] != i) thay v\u00ec \u0111\u1ebfm G\u1ed0C (p[i] == i) \u2014 m\u1ed7i khu b\u1ecb \u0111\u1ebfm theo\n    // s\u1ed1 c\u1ea1nh, kh\u00f4ng ph\u1ea3i s\u1ed1 khu; sai tr\u00ean m\u1ecdi khu c\u00f3 chu\u1ed7i \u2265 1\n    for (int i = 0; i < m; ++i) {\n        int a, b; in >> a >> b;\n        p[b] = a;\n    }\n    int comps = 0;\n    for (int i = 1; i <= n; ++i)\n        if (p[i] != i) ++comps;\n    out << comps << \"\\n\";\n}\n";
R["hsgi-cp18-rain"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    vector<long long> mxL(n), mxR(n);\n    long long m = 0;\n    for (int i = 0; i < n; ++i) { m = max(m, a[i]); mxL[i] = m; }\n    m = 0;\n    for (int i = n - 1; i >= 0; --i) { m = max(m, a[i]); mxR[i] = m; }\n    long long total = 0;\n    for (int i = 0; i < n; ++i)\n        total += max(0LL, min(mxL[i], mxR[i]) - a[i]);\n    out << total << \"\\n\";\n}\n";
W["hsgi-cp18-rain"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    // near-miss: n\u01b0\u1edbc ch\u1ec9 t\u00ednh theo T\u01af\u1edcNG TR\u00c1I \u2014 b\u1ecf t\u01b0\u1eddng ph\u1ea3i\n    long long m = 0, total = 0;\n    for (int i = 0; i < n; ++i) {\n        m = max(m, a[i]);\n        total += max(0LL, m - a[i]);\n    }\n    out << total << \"\\n\";\n}\n";
R["hsgi-cp18-balanced"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; in >> s;\n    int n = s.size();\n    vector<int> st;\n    st.reserve(n + 1);\n    st.push_back(-1);\n    int best = 0;\n    for (int i = 0; i < n; ++i) {\n        if (s[i] == '(') st.push_back(i);\n        else {\n            st.pop_back();\n            if (st.empty()) st.push_back(i);\n            else best = max(best, i - st.back());\n        }\n    }\n    out << best << \"\\n\";\n}\n";
W["hsgi-cp18-balanced"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <deque>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    string s; in >> s;\n    // near-miss: \u0111\u1ebfm s\u1ed1 c\u1eb7p kh\u1edbp \u1edf b\u1ea5t k\u1ef3 \u0111\u00e2u \u2014 b\u1ecf \u0111i\u1ec1u ki\u1ec7n li\u00ean ti\u1ebfp\n    int d = 0, c = 0;\n    for (char ch : s) {\n        if (ch == '(') ++d;\n        else if (d > 0) { --d; c += 2; }\n    }\n    out << c << \"\\n\";\n}\n";
